class DocsError(RuntimeError):
    pass


class Utf8DocsRequestHandler(SimpleHTTPRequestHandler):
    """为浏览器可直接阅读的文本制品显式声明 UTF-8。"""

    def guess_type(self, path: str) -> str:
        # Markdown 原文保留标准 MIME，浏览器默认以源码文本显示；charset 负责中文可读。
        suffix = Path(unquote(path.split("?", 1)[0])).suffix.lower()
        if suffix in {".md", ".markdown"}:
            return "text/markdown; charset=utf-8"
        content_type = super().guess_type(path)
        mime_type = content_type.split(";", 1)[0].strip().lower()
        utf8_types = {
            "application/json",
            "application/javascript",
            "application/xml",
            "application/yaml",
            "application/x-yaml",
            "image/svg+xml",
        }
        if mime_type.startswith("text/") or mime_type in utf8_types:
            return f"{mime_type}; charset=utf-8"
        return content_type


class QuietUtf8DocsRequestHandler(Utf8DocsRequestHandler):
    """Smoke 验收使用的静默处理器，避免把临时 HTTP 请求写入交付输出。"""

    def log_message(self, format: str, *args: object) -> None:  # noqa: A002 - 与标准库签名保持一致
        return


class ChineseArgumentParser(argparse.ArgumentParser):
    """将 argparse 的固定界面文字本地化为中文。"""

    def __init__(self, *args, **kwargs):
        kwargs["add_help"] = False
        super().__init__(*args, **kwargs)
        self._positionals.title = "位置参数"
        self._optionals.title = "选项"
        self.add_argument("-h", "--help", action="help", help="显示帮助并退出")

    def format_usage(self) -> str:
        return super().format_usage().replace("usage:", "用法:", 1)

    def format_help(self) -> str:
        return super().format_help().replace("usage:", "用法:", 1)

    def error(self, message: str) -> None:
        self.print_usage(sys.stderr)
        self.exit(2, f"参数错误：{message}\n")


def configure_utf8_stdio() -> None:
    """保证 Windows 默认代码页不会破坏中文 JSON、错误信息和证据输出。"""
    for stream in [sys.stdout, sys.stderr]:
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except (AttributeError, OSError):
            # 嵌入式解释器或替换过的流可能没有 reconfigure；保留其原有行为。
            continue


def today() -> str:
    return datetime.now(timezone.utc).date().isoformat()


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def project_root(value: str) -> Path:
    root = Path(value).expanduser().resolve()
    if not root.exists() or not root.is_dir():
        raise DocsError(f"项目根目录不存在或不是目录：{root}")
    return root


def validate_project_code(value: str) -> str:
    code = value.strip().upper()
    if not re.fullmatch(r"[A-Z][A-Z0-9]{1,11}", code):
        raise DocsError("项目代码必须为 2 至 12 位大写英文字母或数字，并以字母开头")
    return code


def safe_segment(value: str, label: str) -> str:
    cleaned = re.sub(r"\s+", "-", value.strip())
    cleaned = re.sub(r"[\\/:*?\"<>|]", "-", cleaned)
    cleaned = re.sub(r"-+", "-", cleaned).strip(".- ")
    if not cleaned or cleaned in {".", ".."}:
        raise DocsError(f"{label}无效：{value!r}")
    return cleaned


def render(text: str, values: dict[str, str]) -> str:
    for key, value in values.items():
        text = text.replace("{{" + key + "}}", value)
    return text


def write_new(path: Path, content: str) -> None:
    if path.exists():
        raise DocsError(f"拒绝覆盖已有文件：{path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def write_generated(path: Path, content: str) -> None:
    if path.exists():
        existing = path.read_text(encoding="utf-8")
        if "generated by daoge-docs" not in existing[:200]:
            raise DocsError(f"拒绝覆盖非工具生成的派生文件：{path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def read_json(path: Path, label: str) -> dict:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise DocsError(f"{label}无效：{path}：{exc}") from exc
    if not isinstance(value, dict):
        raise DocsError(f"{label}顶层必须是对象：{path}")
    return value


def write_json(path: Path, value: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def load_profile_catalog() -> dict:
    catalog = read_json(PROFILES_PATH, "文档 Profile 清单")
    if not isinstance(catalog.get("levels"), dict) or not isinstance(catalog.get("documents"), list):
        raise DocsError(f"文档 Profile 清单缺少 levels 或 documents：{PROFILES_PATH}")
    return catalog


def profile_documents(profile: str) -> list[dict]:
    if profile not in PROFILES:
        raise DocsError(f"未知文档 Profile：{profile}")
    catalog = load_profile_catalog()
    levels = catalog["levels"]
    selected = int(levels[profile])
    return [item for item in catalog["documents"] if int(levels[item["level"]]) <= selected]


def load_config(root: Path) -> dict:
    path = root / CONFIG_NAME
    if not path.exists():
        raise DocsError(f"缺少 {CONFIG_NAME}，请先运行 init")
    data = read_json(path, "DAOGE Docs 配置")
    for key in ["project_name", "project_code", "current_version", "docs_root"]:
        if not data.get(key):
            raise DocsError(f"配置缺少字段：{key}")
    data["project_code"] = validate_project_code(str(data["project_code"]))
    data.setdefault("profile", "standard")
    if data["profile"] not in PROFILES:
        raise DocsError(f"配置中的 profile 无效：{data['profile']}")
    return data


def docs_root(root: Path, config: dict) -> Path:
    configured = Path(str(config["docs_root"]))
    if configured.is_absolute() or ".." in configured.parts:
        raise DocsError("docs_root 必须是项目内的相对路径")
    return root / configured


def executable_version(command: list[str]) -> dict:
    """读取可执行文件版本；诊断失败不能阻断不依赖该工具的文档能力。"""
    executable = shutil.which(command[0])
    if not executable:
        return {"available": False, "path": "", "version": ""}
    try:
        result = subprocess.run(command, text=True, capture_output=True, check=False, timeout=5)
    except (OSError, subprocess.TimeoutExpired):
        return {"available": True, "path": executable, "version": ""}
    output = (result.stdout or result.stderr).strip().splitlines()
    return {
        "available": result.returncode == 0,
        "path": executable,
        "version": output[0] if output else "",
    }


def runtime_shell() -> str | None:
    """返回可供 Goal 验证使用的 shell，优先遵循当前平台的原生能力。"""
    if os.name == "nt":
        return None
    for candidate in [os.environ.get("SHELL", ""), "/bin/sh"]:
        if candidate and Path(candidate).exists():
            return candidate
    return None


def windows_shell() -> str | None:
    if os.name != "nt":
        return None
    return next((candidate for candidate in ["pwsh", "powershell"] if command_exists(candidate)), None)


def command_exists(name: str) -> bool:
    return shutil.which(name) is not None


def is_git_worktree(root: Path) -> bool:
    """兼容普通仓库、linked worktree 与 CI checkout 的 Git 工作树判断。"""
    if not command_exists("git"):
        return False
    result = subprocess.run(
        ["git", "rev-parse", "--is-inside-work-tree"],
        cwd=root,
        text=True,
        capture_output=True,
        check=False,
    )
    return result.returncode == 0 and result.stdout.strip().lower() == "true"


def detect_stack_adapters(root: Path) -> list[dict]:
    """从通用工程文件派生候选技术栈与验证建议，不猜测项目业务语义。"""
    adapters: list[dict] = []

    def add(identifier: str, label: str, evidence: list[str], commands: list[str], limitations: list[str]) -> None:
        adapters.append(
            {
                "id": identifier,
                "name": label,
                "evidence": evidence,
                "suggested_commands": commands,
                "limitations": limitations,
                "contract_version": STACK_ADAPTER_CONTRACT_VERSION,
            }
        )

    if (root / "package.json").is_file():
        lockfiles = [name for name in ["pnpm-lock.yaml", "yarn.lock", "package-lock.json", "bun.lockb"] if (root / name).exists()]
        package_manager = "pnpm" if "pnpm-lock.yaml" in lockfiles or (root / "pnpm-workspace.yaml").is_file() else "yarn" if "yarn.lock" in lockfiles else "npm"
        evidence = ["package.json", *lockfiles]
        if (root / "pnpm-workspace.yaml").is_file():
            evidence.append("pnpm-workspace.yaml")
        add(
            "node",
            "Node.js / TypeScript",
            evidence,
            [f"{package_manager} run lint", f"{package_manager} test", f"{package_manager} run build"],
            ["必须先读取 package.json scripts；建议命令不是项目已确认的验收命令。"],
        )
    if (root / "pyproject.toml").is_file() or (root / "requirements.txt").is_file() or (root / "setup.py").is_file():
        evidence = [name for name in ["pyproject.toml", "requirements.txt", "setup.py"] if (root / name).is_file()]
        add(
            "python",
            "Python",
            evidence,
            ["python -m pytest", "python -m unittest discover", "python -m ruff check ."],
            ["必须从 pyproject.toml、tox.ini 或现有 CI 确认实际测试与静态检查入口。"],
        )
    if (root / "go.mod").is_file():
        add("go", "Go", ["go.mod"], ["go test ./...", "go vet ./...", "go build ./..."], ["需结合 workspace、生成代码和私有模块配置确认。"])
    if (root / "Cargo.toml").is_file():
        add("rust", "Rust", ["Cargo.toml"], ["cargo fmt --check", "cargo clippy -- -D warnings", "cargo test"], ["需结合 Cargo workspace 与 feature flags 确认。"])
    if (root / "pom.xml").is_file():
        add("java-maven", "Java / Maven", ["pom.xml"], ["mvn test", "mvn verify"], ["需结合 Maven profile、JDK 与集成测试配置确认。"])
    if (root / "build.gradle").is_file() or (root / "build.gradle.kts").is_file():
        evidence = [name for name in ["build.gradle", "build.gradle.kts", "gradlew"] if (root / name).is_file()]
        executable = "./gradlew" if (root / "gradlew").is_file() else "gradle"
        add("java-gradle", "Java / Kotlin / Gradle", evidence, [f"{executable} test", f"{executable} check"], ["Windows 必须使用 gradlew.bat 或平台对应命令。"])
    if (root / "Gemfile").is_file():
        add("ruby", "Ruby", ["Gemfile"], ["bundle exec rake test", "bundle exec rubocop"], ["需结合 Rakefile 与测试框架确认。"])
    if (root / "composer.json").is_file():
        add("php", "PHP / Composer", ["composer.json"], ["composer test", "composer lint"], ["需从 composer scripts 确认命令。"])
    if any(root.glob("*.sln")) or any(root.glob("*.csproj")):
        evidence = [path.name for path in sorted([*root.glob("*.sln"), *root.glob("*.csproj")])]
        add("dotnet", ".NET", evidence, ["dotnet test", "dotnet build"], ["需结合 solution、Target Framework 与本地 SDK 确认。"])
    if (root / "pnpm-workspace.yaml").is_file() or (root / "turbo.json").is_file() or (root / "nx.json").is_file() or (root / "lerna.json").is_file():
        evidence = [name for name in ["pnpm-workspace.yaml", "turbo.json", "nx.json", "lerna.json"] if (root / name).is_file()]
        add("monorepo", "Monorepo", evidence, ["先读取 workspace 配置，再按受影响包执行验证"], ["Goal 的 allowed_paths 与验证命令必须精确到包/服务，不能用根目录全量猜测。"])
    return adapters


def docs_doctor(root: Path, config: dict | None = None) -> dict:
    """输出面向安装与升级的只读环境诊断。"""
    python_ok = sys.version_info >= MIN_PYTHON_VERSION
    git_info = executable_version(["git", "--version"])
    node_info = executable_version(["node", "--version"])
    npm_info = executable_version(["npm", "--version"])
    shell = runtime_shell()
    findings: list[dict] = []

    def finding(code: str, level: str, message: str, fix: str) -> None:
        findings.append({"code": code, "level": level, "message": message, "fix": fix})

    if not python_ok:
        finding("PYTHON_VERSION", "error", f"当前 Python {platform.python_version()} 低于最低要求 3.10。", "安装 Python 3.10 或更高版本，并用该解释器运行 daoge_docs.py。")
    if not git_info["available"]:
        finding("GIT_MISSING", "warning", "未发现 Git；文档初始化和检查可用，但 Goal、检查点与提交绑定不可用。", "安装 Git 并确保 git 在 PATH 中。")
    windows_goal_shell = windows_shell()
    if os.name == "nt" and not command_exists("py"):
        finding("WINDOWS_PYTHON_LAUNCHER", "warning", "Windows 未发现 py 启动器。", "确认 python 或 py 命令在 PATH 中；文档中的命令请使用实际可用的启动器。")
    if os.name != "nt" and not shell:
        finding("SHELL_MISSING", "warning", "未发现可用于 Goal 验证的 POSIX shell。", "安装并配置 POSIX shell，或在功能 AC 中使用可跨平台的验证方式。")
    git_worktree = is_git_worktree(root)
    if not git_worktree:
        finding("GIT_REPOSITORY", "warning", "当前目录不是 Git 工作树；Goal 的确定性检查点不可用。", "先初始化 Git 并创建基线提交，再执行 prepare-goal。")
    if config is None:
        finding("NOT_INITIALIZED", "info", "当前项目尚未初始化 DAOGE Docs。", "运行 init，或在已有 docs 项目中使用 init --merge。")
    if os.name == "nt" and not windows_goal_shell:
        finding("WINDOWS_SHELL", "error", "未发现 PowerShell 或 pwsh，无法执行 Goal 验证命令。", "安装 PowerShell 并确保 powershell 或 pwsh 在 PATH 中。")
    elif os.name == "nt":
        finding("WINDOWS_SHELL", "info", "Windows 上 Goal 验证通过 PowerShell 执行；功能规格中的验证命令应使用 PowerShell 或跨平台命令。", "避免在 AC 中写仅适用于 Bash 的语法。")

    return {
        "诊断": "daoge-docs-doctor",
        "通过": not any(item["level"] == "error" for item in findings),
        "工具版本": TOOL_VERSION,
        "系统": {"name": platform.system(), "release": platform.release(), "machine": platform.machine(), "os_name": os.name},
        "运行时": {
            "python": {"version": platform.python_version(), "minimum": ".".join(map(str, MIN_PYTHON_VERSION)), "compatible": python_ok, "executable": sys.executable},
            "git": git_info,
            "node": node_info,
            "npm": npm_info,
            "goal_shell": windows_goal_shell or (shell or ""),
        },
        "项目": {"root": str(root), "initialized": config is not None, "git_worktree": git_worktree, "docs_root": str(config.get("docs_root", "")) if config else ""},
        "技术栈候选": detect_stack_adapters(root),
        "发现": findings,
        "边界": "技术栈候选来自仓库文件，不会执行安装、构建或测试。实际 AC 验证命令必须由项目规格冻结。",
    }


def values_for(config: dict, version: str | None = None) -> dict[str, str]:
    return {
        "PROJECT_NAME": str(config["project_name"]),
        "PROJECT_CODE": str(config["project_code"]),
        "VERSION": version or str(config["current_version"]),
        "DATE": today(),
    }


def project_python_command() -> str:
    """生成写入派生文档的跨平台 Python 命令模板。"""
    return "python3" if os.name != "nt" else "py -3"


def chain_project_commands(left: str, right: str) -> str:
    """为当前平台生成在首个命令失败时停止的串行命令。"""
    if os.name == "nt":
        return f"{left}; if ($LASTEXITCODE -eq 0) {{ {right} }}"
    return f"{left} && {right}"


def rendered_profile_path(item: dict, values: dict[str, str]) -> Path:
    return Path(render(str(item["path"]), values))


def render_sections(sections: list) -> str:
    blocks: list[str] = []
    for number, section in enumerate(sections, start=2):
        if isinstance(section, dict):
            title = str(section.get("title", "未命名章节"))
            guidance = str(section.get("guidance", "说明确定结论、依据、边界和验证方式。"))
        else:
            title = str(section)
            guidance = f"说明“{title}”的确定结论、依据、适用边界和验证方式。"
        blocks.extend([f"## {number}. {title}", "", f"[待填写：{guidance}]", ""])
        headers = STRUCTURED_SECTION_SCAFFOLDS.get(title)
        if headers:
            blocks.extend(
                [
                    "| " + " | ".join(headers) + " |",
                    "| " + " | ".join("---" for _ in headers) + " |",
                    "| " + " | ".join(f"[待填写：{header}]" for header in headers) + " |",
                    "",
                ]
            )
    return "\n".join(blocks).rstrip()


def render_profile_document(item: dict, config: dict, version: str, index: int) -> str:
    values = values_for(config, version)
    values.update(
        {
            "DOC_ID": f"{config['project_code']}-DOC-{index:03d}-{version}",
            "TITLE": render(str(item["title"]), values),
            "AUTHORITY": render(str(item["authority"]), values),
            "PURPOSE": render(str(item["purpose"]), values),
            "SECTIONS": render_sections(item.get("sections", [])),
            "PYTHON_COMMAND": project_python_command(),
        }
    )
    if item.get("source"):
        source = ASSETS / str(item["source"])
        if not source.exists():
            raise DocsError(f"Profile 引用的模板不存在：{source}")
        return render(source.read_text(encoding="utf-8"), values)
    path_text = str(item["path"])
    title = str(item["title"])
    if Path(path_text).name == "README.md":
        template_name = "导航文档.md"
    elif "验证证据" in title or "证据登记" in title:
        template_name = "证据文档.md"
    elif "手册" in title:
        template_name = "执行手册.md"
    elif any(word in title for word in ["矩阵", "索引", "路线图"]):
        template_name = "矩阵文档.md"
    else:
        template_name = "规格文档.md"
    template = (DOCUMENT_TEMPLATES / template_name).read_text(encoding="utf-8")
    return render(template, values)


def materialize_profile(root: Path, config: dict, version: str) -> tuple[list[str], list[str]]:
    target_docs = docs_root(root, config)
    created: list[str] = []
    skipped: list[str] = []
    catalog = load_profile_catalog()
    all_documents = catalog["documents"]
    selected_level = int(catalog["levels"][str(config["profile"])])
    for index, item in enumerate(all_documents, start=1):
        if int(catalog["levels"][item["level"]]) > selected_level:
            continue
        destination = target_docs / rendered_profile_path(item, values_for(config, version))
        if item.get("generated"):
            continue
        if destination.exists():
            skipped.append(str(destination.relative_to(root)))
            continue
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(render_profile_document(item, config, version, index), encoding="utf-8")
        created.append(str(destination.relative_to(root)))
    return created, skipped


def vendor_tooling(root: Path, overwrite: bool = False) -> tuple[list[str], list[str]]:
    tooling = root / ".daoge-docs"
    tooling.mkdir(parents=True, exist_ok=True)
    created: list[str] = []
    skipped: list[str] = []
    targets = [(SCRIPT_PATH, tooling / "daoge_docs.py")]
    for source in sorted(ASSETS.rglob("*")):
        if source.is_file():
            targets.append((source, tooling / "assets" / source.relative_to(ASSETS)))
    for source, destination in targets:
        # An in-project tool may be asked to upgrade its own checkout. Treat
        # that source/target pair as already current instead of copying a file
        # onto itself (which raises shutil.SameFileError on macOS/Linux).
        try:
            if destination.exists() and source.resolve() == destination.resolve():
                skipped.append(str(destination.relative_to(root)))
                continue
        except OSError:
            pass
        if destination.exists() and not overwrite:
            skipped.append(str(destination.relative_to(root)))
            continue
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, destination)
        created.append(str(destination.relative_to(root)))
    return created, skipped


def parse_frontmatter(text: str) -> dict[str, str]:
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return {}
    result: dict[str, str] = {}
    for line in lines[1:]:
        if line.strip() == "---":
            return result
        if not line.strip() or line.lstrip().startswith("#") or ":" not in line:
            continue
        key, value = line.split(":", 1)
        result[key.strip()] = value.strip().strip("\"'")
    return {}


def markdown_title(text: str) -> str:
    for line in text.splitlines():
        if line.startswith("# "):
            return line[2:].strip()
    return "未命名文档"


def list_field(value: str) -> list[str]:
    if not value or value.lower() in {"none", "n/a"}:
        return []
    return [item.strip() for item in re.split(r"[,，]", value) if item.strip()]


def normalize_goal_paths(value: str) -> list[str]:
    """解析功能声明的工程路径，统一分隔符并保持稳定排序。"""
    paths = {normalize_repo_path(item) for item in list_field(value)}
    return sorted(path for path in paths if path)


def normalize_repo_path(value: object) -> str:
    """将 Git、Goal 与文档中使用的项目相对路径统一为 POSIX 形式。"""
    return str(value or "").strip().replace("\\", "/").rstrip("/")


def normalize_doc_source(root: Path, config: dict, value: object) -> tuple[str, str]:
    """把来源统一为 docs 相对路径；无法定位的文字保留为说明而非伪造路径。"""
    raw = str(value or "").strip().replace("\\", "/")
    if not raw:
        return "", ""
    docs = docs_root(root, config).resolve()
    candidate: Path
    try:
        candidate = Path(raw).expanduser()
        if candidate.is_absolute():
            resolved = candidate.resolve()
        else:
            resolved = (root / candidate).resolve()
            if not resolved.exists():
                resolved = (docs / candidate).resolve()
        resolved.relative_to(docs)
    except (OSError, ValueError):
        return "", raw
    if not resolved.exists():
        return "", raw
    return resolved.relative_to(docs).as_posix(), ""


def goal_path_conflicts(left: Iterable[str], right: Iterable[str]) -> list[tuple[str, str]]:
    """返回路径授权与禁止声明之间的文件/目录边界冲突。"""
    conflicts: list[tuple[str, str]] = []
    for left_path in sorted(set(left)):
        for right_path in sorted(set(right)):
            if goal_path_matches(left_path, [right_path]) or goal_path_matches(right_path, [left_path]):
                conflicts.append((left_path, right_path))
    return conflicts


def feature_documents(root: Path, config: dict, version: str | None = None) -> list[dict]:
    active_version = version or str(config["current_version"])
    base = docs_root(root, config) / "03-功能规格" / active_version
    records: list[dict] = []
    if not base.exists():
        return records
    prefix = re.compile(rf"^{re.escape(config['project_code'])}-FR-(\d{{3}})$")
    for path in sorted(base.rglob("*.md")):
        if path.name.endswith("-技术设计.md") or path.name == "README.md" or "开发任务" in path.parts:
            continue
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        match = prefix.fullmatch(meta.get("id", ""))
        if match:
            records.append(
                {"path": path, "text": text, "meta": meta, "number": int(match.group(1)), "title": markdown_title(text)}
            )
    return sorted(records, key=lambda record: (record["number"], str(record["meta"].get("id", ""))))


def all_feature_documents(root: Path, config: dict) -> list[dict]:
    """Return feature specifications for every registered/versioned feature space.

    Gate and execution data intentionally keep using ``feature_documents`` for the
    active version.  Portfolio, audit and static diagrams need the complete
    project slice, including historical and future version directories.
    """
    feature_root = docs_root(root, config) / "03-功能规格"
    if not feature_root.exists():
        return []
    version_ids = {path.name.upper() for path in feature_root.iterdir() if path.is_dir() and re.fullmatch(r"V\d+", path.name, re.IGNORECASE)}
    version_ids.add(str(config["current_version"]).upper())
    records: list[dict] = []
    seen: set[str] = set()
    for version_id in sorted(version_ids, key=lambda value: (int(value[1:]) if value[1:].isdigit() else 9999, value)):
        for record in feature_documents(root, config, version_id):
            feature_id = str(record["meta"].get("id", ""))
            if feature_id and feature_id not in seen:
                seen.add(feature_id)
                records.append(record)
    return sorted(records, key=lambda record: (int(record["meta"].get("version", "V9999")[1:]) if str(record["meta"].get("version", "")).startswith("V") and str(record["meta"].get("version", "V")[1:]).isdigit() else 9999, record["number"], str(record["meta"].get("id", ""))))


def adr_documents(root: Path, config: dict) -> list[dict]:
    base = docs_root(root, config) / "06-决策记录" / "ADR"
    records: list[dict] = []
    if not base.exists():
        return records
    for path in sorted(base.glob("[0-9][0-9][0-9][0-9]-*.md")):
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        match = re.fullmatch(r"ADR-(\d{4})", meta.get("id", ""))
        if match:
            records.append(
                {"path": path, "text": text, "meta": meta, "number": int(match.group(1)), "title": markdown_title(text)}
            )
    return records


def adr_statuses(root: Path, config: dict) -> dict[str, str]:
    """Return ADR lifecycle state by stable ID for feature authorization checks."""
    return {
        str(record["meta"].get("id", "")): str(record["meta"].get("status", "proposed"))
        for record in adr_documents(root, config)
        if record["meta"].get("id")
    }


def e2e_documents(root: Path, config: dict) -> list[dict]:
    base = docs_root(root, config) / "05-测试与发布" / "端到端验收" / "用例"
    records: list[dict] = []
    if not base.exists():
        return records
    for path in sorted(base.glob("E2E-[0-9][0-9][0-9]-*.md")):
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        match = re.fullmatch(r"E2E-(\d{3})", meta.get("id", ""))
        if match:
            records.append({"path": path, "text": text, "meta": meta, "number": int(match.group(1)), "title": markdown_title(text)})
    return records


def current_e2e_documents(root: Path, config: dict) -> list[dict]:
    """Return E2E cases belonging to the active version.

    E2E documents are retained as historical evidence after a version switch, but
    current requirements and release evidence must never be forced to reference
    another version's frozen feature IDs.
    """
    version = str(config["current_version"])
    return [record for record in e2e_documents(root, config) if str(record["meta"].get("version", "")) == version]


def decisions_path(root: Path, config: dict, version: str | None = None) -> Path:
    selected = version or str(config["current_version"])
    return docs_root(root, config) / "06-决策记录" / f"{selected}-冻结决策注册表.json"


def ensure_decisions(root: Path, config: dict, version: str) -> Path:
    path = decisions_path(root, config, version)
    if not path.exists():
        write_json(path, {"schema_version": 1, "version": version, "items": []})
    return path


def decision_records(root: Path, config: dict, version: str | None = None) -> list[dict]:
    path = decisions_path(root, config, version)
    if not path.exists():
        return []
    data = read_json(path, "冻结决策注册表")
    if not isinstance(data.get("items"), list):
        raise DocsError(f"冻结决策注册表 items 必须是数组：{path}")
    return [item for item in data["items"] if isinstance(item, dict)]


def requirements_path(root: Path, config: dict, version: str | None = None) -> Path:
    selected = version or str(config["current_version"])
    return docs_root(root, config) / "03-功能规格" / selected / f"00-{selected}需求注册表.json"


def ensure_requirements(root: Path, config: dict, version: str) -> Path:
    path = requirements_path(root, config, version)
    if not path.exists():
        write_json(path, {"schema_version": 1, "version": version, "items": []})
    return path


def requirement_records(root: Path, config: dict, version: str | None = None) -> list[dict]:
    selected = version or str(config["current_version"])
    records: list[dict] = []
    for feature in feature_documents(root, config, selected):
        records.append(
            {
                "id": feature["meta"]["id"],
                "type": "FR",
                "title": feature["title"],
                "status": feature["meta"].get("status", "draft"),
                "source": feature["path"].relative_to(docs_root(root, config)).as_posix(),
            }
        )
    path = requirements_path(root, config, selected)
    if path.exists():
        data = read_json(path, "需求注册表")
        if not isinstance(data.get("items"), list):
            raise DocsError(f"需求注册表 items 必须是数组：{path}")
        records.extend(item for item in data["items"] if isinstance(item, dict))
    return records


def acceptance_rows(text: str) -> list[list[str]]:
    rows: list[list[str]] = []
    for line in text.splitlines():
        if re.match(r"^\|\s*AC\d{2,}\s*\|", line):
            rows.append([cell.strip() for cell in line.strip().strip("|").split("|")])
    complete_rows = [row for row in rows if len(row) >= 8]
    return complete_rows or rows


def markdown_section(text: str, title: str) -> str:
    """返回包含 title 的 Markdown 章节正文，不依赖章节编号。"""
    lines = text.splitlines()
    for index, line in enumerate(lines):
        match = re.match(r"^(#{1,6})\s+(.+?)\s*$", line)
        if not match or title not in match.group(2):
            continue
        level = len(match.group(1))
        end = len(lines)
        for cursor in range(index + 1, len(lines)):
            next_heading = re.match(r"^(#{1,6})\s+", lines[cursor])
            if next_heading and len(next_heading.group(1)) <= level:
                end = cursor
                break
        return "\n".join(lines[index:end])
    return ""


def markdown_row_cells(line: str) -> list[str]:
    """解析简单 Markdown 表格行，保留单元格正文并支持转义竖线。"""
    stripped = line.strip()
    if stripped.startswith("|"):
        stripped = stripped[1:]
    if stripped.endswith("|") and not stripped.endswith(r"\|"):
        stripped = stripped[:-1]
    return [cell.replace(r"\|", "|").strip() for cell in re.split(r"(?<!\\)\|", stripped)]


def markdown_table_rows(text: str, required_headers: Iterable[str]) -> list[dict[str, str]]:
    headers = [str(item) for item in required_headers]
    lines = text.splitlines()
    for index in range(len(lines) - 1):
        if "|" not in lines[index] or "|" not in lines[index + 1]:
            continue
        actual_headers = markdown_row_cells(lines[index])
        separator = markdown_row_cells(lines[index + 1])
        if actual_headers != headers or len(separator) != len(headers):
            continue
        if not all(re.fullmatch(r":?-{3,}:?", cell.replace(" ", "")) for cell in separator):
            continue
        rows: list[dict[str, str]] = []
        for line in lines[index + 2 :]:
            if not line.strip() or "|" not in line:
                break
            cells = markdown_row_cells(line)
            if len(cells) != len(headers):
                break
            rows.append(dict(zip(headers, cells)))
        return rows
    return []


def markdown_table_rows_with_optional_headers(
    text: str, required_headers: Iterable[str], optional_headers: Iterable[str] = ()
) -> tuple[list[dict[str, str]], list[str]]:
    """Read a structured table while permitting explicitly registered trailing columns.

    The caller still controls the required contract.  Optional columns are never
    inferred from table prose, which keeps an older authority table compatible
    without creating a second source of version facts.
    """
    headers = [str(item) for item in required_headers]
    allowed_optional = [str(item) for item in optional_headers]
    lines = text.splitlines()
    for index in range(len(lines) - 1):
        if "|" not in lines[index] or "|" not in lines[index + 1]:
            continue
        actual_headers = markdown_row_cells(lines[index])
        if actual_headers[: len(headers)] != headers:
            continue
        optional = actual_headers[len(headers) :]
        if any(item not in allowed_optional for item in optional):
            continue
        separator = markdown_row_cells(lines[index + 1])
        if len(separator) != len(actual_headers) or not all(
            re.fullmatch(r":?-{3,}:?", cell.replace(" ", "")) for cell in separator
        ):
            continue
        rows: list[dict[str, str]] = []
        for line in lines[index + 2 :]:
            if not line.strip() or "|" not in line:
                break
            cells = markdown_row_cells(line)
            if len(cells) != len(actual_headers):
                break
            rows.append(dict(zip(actual_headers, cells)))
        return rows, actual_headers
    return [], []


def has_markdown_table_with_optional_headers(
    text: str, required_headers: Iterable[str], optional_headers: Iterable[str] = ()
) -> bool:
    _rows, headers = markdown_table_rows_with_optional_headers(text, required_headers, optional_headers)
    return bool(headers)


def has_markdown_table(text: str, required_headers: Iterable[str]) -> bool:
    headers = [str(item) for item in required_headers]
    lines = text.splitlines()
    for index in range(len(lines) - 1):
        if markdown_row_cells(lines[index]) != headers:
            continue
        separator = markdown_row_cells(lines[index + 1])
        if len(separator) == len(headers) and all(
            re.fullmatch(r":?-{3,}:?", cell.replace(" ", "")) for cell in separator
        ):
            return True
    return False


def meaningful_structured_row(row: dict[str, str]) -> bool:
    values = list(row.values())
    return bool(values) and all(value and value not in {"-", "none", "n/a"} and not incomplete(value) for value in values)


def meaningful_evolution_relation_row(row: dict[str, str]) -> bool:
    relation_type = str(row.get("关系类型", "")).strip().lower()
    required = ["关系 ID", "关系类型", "影响与处理", "状态与来源"]
    if relation_type not in {"none", "无", "无关系", "不适用"}:
        required.append("来源版本/里程碑")
        if not any(word in relation_type for word in ["废弃", "deprecation", "deprecated"]):
            required.append("目标版本/里程碑")
    for header in required:
        value = str(row.get(header, "")).strip()
        if not value or value.lower() in {"-", "n/a"}:
            return False
        if header == "关系类型" and relation_type in {"none", "无", "无关系", "不适用"}:
            continue
        if incomplete(value):
            return False
    return True


def clean_markdown_cell(value: str) -> str:
    cleaned = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", str(value))
    return cleaned.replace("`", "").strip()


def fenced_code_blocks(text: str) -> list[str]:
    return [match.group(1).strip() for match in re.finditer(r"```[^\n]*\n(.*?)\n```", text, re.DOTALL)]


def design_branch_ids(text: str) -> list[str]:
    return sorted(set(re.findall(r"\bB\d{2,3}-\d{2,}\b", text)))


def acceptance_ids(text: str) -> list[str]:
    return sorted(set(re.findall(r"^\|\s*(AC\d{2,})\s*\|", text, re.MULTILINE)))


def design_depth(text: str, high_risk: bool = False) -> dict:
    pseudocode = markdown_section(text, "伪代码")
    trace = markdown_section(text, "分支追踪") or markdown_section(text, "分支到测试追踪")
    blocks = fenced_code_blocks(pseudocode)
    pseudocode_payload = "\n".join(blocks).strip()
    required = ["函数/用例签名", "伪代码", "分支追踪"] if high_risk else ["单元契约", "伪代码", "分支到测试追踪"]
    if high_risk:
        required.extend(["事务、并发与幂等", "外部调用、重试与补偿"])
    branches = design_branch_ids(text)
    return {
        "required_sections": required,
        "missing_sections": missing_headings(text, required),
        "has_pseudocode_block": bool(blocks),
        "pseudocode_complete": bool(pseudocode_payload) and not incomplete(pseudocode_payload),
        "pseudocode_executable": bool(
            pseudocode_payload
            and not incomplete(pseudocode_payload)
            and re.search(r"\b(?:function|if|when|return|begin|commit|rollback|require)\b|如果|返回|事务|校验|调用", pseudocode_payload, re.IGNORECASE)
        ),
        "branch_ids": branches,
        "trace_branch_ids": design_branch_ids(trace),
        "trace_acceptance_ids": sorted(set(re.findall(r"\bAC\d{2,}\b", trace))),
    }


def validate_feature_design_depth(record: dict) -> list[str]:
    errors: list[str] = []
    feature_id = str(record["meta"].get("id", record["path"]))
    feature_acceptance = acceptance_ids(record["text"])
    main_depth = design_depth(record["text"])
    for title in main_depth["missing_sections"]:
        errors.append(f"{feature_id} 功能主文档缺少可解释设计章节“{title}”")
    if not main_depth["has_pseudocode_block"]:
        errors.append(f"{feature_id} 功能主文档伪代码缺少 fenced code block")
    if not main_depth["branch_ids"]:
        errors.append(f"{feature_id} 功能主文档缺少稳定分支 ID")
    if not main_depth["trace_branch_ids"]:
        errors.append(f"{feature_id} 功能主文档分支追踪表没有稳定分支 ID")

    trace_acceptance = set(main_depth["trace_acceptance_ids"])
    if record["meta"].get("risk") == "high":
        design_path = record["path"].with_name(record["path"].stem + "-技术设计.md")
        if not design_path.exists():
            return errors
        design_text = design_path.read_text(encoding="utf-8")
        high_depth = design_depth(design_text, high_risk=True)
        for title in high_depth["missing_sections"]:
            errors.append(f"{feature_id} 高风险技术设计缺少章节“{title}”")
        if not high_depth["has_pseudocode_block"]:
            errors.append(f"{feature_id} 高风险技术设计伪代码缺少 fenced code block")
        if len(high_depth["branch_ids"]) < 2:
            errors.append(f"{feature_id} 高风险技术设计至少需要 2 个稳定分支 ID")
        if not high_depth["trace_branch_ids"]:
            errors.append(f"{feature_id} 高风险技术设计分支追踪表没有稳定分支 ID")
        trace_acceptance.update(high_depth["trace_acceptance_ids"])
    missing_acceptance = sorted(set(feature_acceptance) - trace_acceptance)
    if missing_acceptance:
        errors.append(f"{feature_id} AC 未进入分支追踪：{', '.join(missing_acceptance)}")
    return errors


