    for record in feature_documents(root, config):
        meta = record["meta"]
        rel = os.path.relpath(record["path"], index_dir).replace(os.sep, "/")
        lines.append(
            f"| `{meta['id']}` | [{record['title']}]({rel}) | {meta.get('domain', '未分类')} | "
            f"{meta.get('status', 'draft')} | {meta.get('risk', 'standard')} | {meta.get('updated', '未知')} |"
        )
    if len(lines) == 5:
        lines.append("| - | 当前没有功能规格 | - | - | - | - |")
    return "\n".join(lines + ["", "本索引由功能文档 front matter 生成。", ""])


