    version = str(config["current_version"])
    lines = [
        GENERATED_MARKER,
        f"# {version} 实现状态",
        "",
        "> 本页只汇总可以追溯的实现信号，不改变需求定义；unknown 不得解释为未实现或已实现。",
        "",
        "| 功能 ID | 后端 | 前端 | 数据/迁移 | 自动化验证 | 当前差距 | 证据 | 更新时间 |",
        "| --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for record in feature_documents(root, config):
        signal = feature_implementation_signal(root, record)
        lines.append(
            f"| `{record['meta']['id']}` | {signal['backend']} | {signal['frontend']} | {signal['data']} | "
            f"{signal['automated_verification']} | {signal['gap']} | {signal['evidence']} | {record['meta'].get('updated', '未知')} |"
        )
    if len(lines) == 7:
        lines.append("| - | unknown | unknown | unknown | not_run | 当前没有功能规格 | 无 | 未知 |")
    return "\n".join(lines + [""])


