def command_new_decision(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    path = ensure_decisions(root, config, str(config["current_version"]))
    data = read_json(path, "冻结决策注册表")
    items = data.setdefault("items", [])
    numbers = []
    for item in items:
        match = re.fullmatch(r"D(\d{3})", str(item.get("id", ""))) if isinstance(item, dict) else None
        if match:
            numbers.append(int(match.group(1)))
    number = max(numbers, default=0) + 1
    decision_id = f"D{number:03d}"
    status = args.status
    if status == "accepted" and not args.confirmed_by:
        raise DocsError("accepted 决策必须提供 --confirmed-by，不能由工具自行批准")
    items.append(
        {
            "id": decision_id,
            "title": args.title.strip(),
            "status": status,
            "decision": args.decision.strip(),
            "rationale": args.rationale.strip(),
            "requirements": args.requirements.strip() or "none",
            "affected": args.affected.strip(),
            "confirmed_by": args.confirmed_by.strip() or None,
            "confirmed_at": now_iso() if status == "accepted" else None,
            "supersedes": args.supersedes.strip() or "none",
            "updated": today(),
        }
    )
    write_json(path, data)
    generate_indexes(root, config)
    return {"状态": "已登记冻结决策", "决策 ID": decision_id, "决策状态": status, "注册表": str(path.relative_to(root))}


