def required_profile_paths(config: dict) -> list[Path]:
    values = values_for(config)
    return [rendered_profile_path(item, values) for item in profile_documents(str(config["profile"]))]


def validate_workbench_table_contracts(root: Path, config: dict) -> list[str]:
    if config.get("profile") != "strict":
        return []
    docs = docs_root(root, config)
    values = values_for(config)
    errors: list[str] = []
    for contract in WORKBENCH_TABLE_CONTRACTS.values():
        relative = Path(render(str(contract["path"]), values))
        path = docs / relative
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8")
        section = markdown_section(text, str(contract["section"]))
        if not section or not has_markdown_table_with_optional_headers(
            section, contract["headers"], contract.get("optional_headers", [])
        ):
            errors.append(
                f"开发工作台结构化表格缺失或列名不符：{relative}#{contract['section']}："
                + " | ".join(contract["headers"])
            )
    return errors


def browser_doc_path(docs: Path, value: object) -> Path | None:
    raw = str(value or "").strip().replace("\\", "/")
    if not raw or raw.startswith(("http://", "https://", "#")):
        return None
    candidate = Path(raw)
    try:
        if candidate.is_absolute():
            resolved = candidate.resolve()
        else:
            resolved = (docs / candidate).resolve()
            if not resolved.exists() and candidate.parts and candidate.parts[0] == docs.name:
                resolved = (docs.parent / candidate).resolve()
        resolved.relative_to(docs.resolve())
    except (OSError, ValueError):
        return None
    return resolved


def browser_source_paths(value: object) -> Iterable[str]:
    if isinstance(value, dict):
        for key, item in value.items():
            if key == "source_path" and isinstance(item, str) and item.strip():
                yield item
            elif key == "source_paths" and isinstance(item, list):
                yield from (str(path) for path in item if isinstance(path, str) and path.strip())
            else:
                yield from browser_source_paths(item)
    elif isinstance(value, list):
        for item in value:
            yield from browser_source_paths(item)


def validate_browser_contract(root: Path, config: dict) -> list[str]:
    """校验浏览器派生数据的来源闭合和人类交互契约。"""
    docs = docs_root(root, config)
    payload = browser_payload(root, config)
    errors: list[str] = []
    required_views = {"workbench", "overview", "reader", "maps", "evolution", "timelines"}
    required_maps = {
        "product_architecture",
        "core_flow",
        "version_roadmap",
        "data_domains",
        "delivery_trace",
        "risk_hotspots",
    }
    if payload.get("schema_version") != 8:
        errors.append("工作台数据契约 schema_version 必须为 8")
    if set((payload.get("views") or {})) != required_views:
        errors.append("工作台六视图数据不完整：必须包含工作台、总览、阅读、图谱、功能演进和时间线")
    maps = (payload.get("views") or {}).get("maps") or {}
    if set(maps) != required_maps:
        errors.append("工作台六类图谱数据不完整")
    allowed_map_statuses = {"ready", "blocked", "unknown"}
    for map_id, model in maps.items():
        status = str(model.get("status", ""))
        nodes = model.get("nodes") or []
        edges = model.get("edges") or []
        findings = model.get("findings") or []
        if status not in allowed_map_statuses:
            errors.append(f"图谱状态无效：{map_id}={status}")
        if status == "ready" and (not nodes or findings):
            errors.append(f"图谱错误标记为已就绪：{map_id}")
        node_ids = {str(item.get("id", "")) for item in nodes if item.get("id")}
        if len(node_ids) != len(nodes):
            errors.append(f"图谱节点 ID 缺失或重复：{map_id}")
        for node in nodes:
            if not node.get("sources") or not any(item.get("source_path") for item in node.get("sources") or []):
                errors.append(f"图谱节点缺少权威来源：{map_id}/{node.get('id', '')}")
            if status == "ready" and incomplete(str(node.get("label", ""))):
                errors.append(f"已就绪图谱仍含待决节点：{map_id}/{node.get('id', '')}")
        for edge in edges:
            if edge.get("from") not in node_ids or edge.get("to") not in node_ids:
                errors.append(f"图谱关系引用未知节点：{map_id}/{edge.get('from', '')}->{edge.get('to', '')}")
            if not edge.get("sources") or not any(item.get("source_path") for item in edge.get("sources") or []):
                errors.append(f"图谱关系缺少权威来源：{map_id}/{edge.get('from', '')}->{edge.get('to', '')}")
    for node in (maps.get("version_roadmap") or {}).get("nodes", []):
        if node.get("type") == "version" and not node.get("planning_status"):
            errors.append(f"版本路线节点缺少规划状态：{node.get('id', '')}")
    for node in (maps.get("risk_hotspots") or {}).get("nodes", []):
        if node.get("type") == "risk" and not node.get("severity"):
            errors.append(f"风险热区节点缺少等级：{node.get('id', '')}")
    overview = (payload.get("views") or {}).get("overview") or {}
    active_execution_version = str(config.get("current_version", ""))
    workbench = (payload.get("views") or {}).get("workbench") or {}
    portfolio = workbench.get("version_portfolio") or {}
    project_features = payload.get("project_features") or []
    required_overview = {
        "scope", "stats", "product_architecture", "core_flow", "version_chain",
        "development_progress", "accepted_decisions", "authority_entries",
    }
    if set(overview) != required_overview:
        errors.append("总览数据不完整：必须包含指标、三类主关系、交付进度、决策和权威入口")
    overview_scope = overview.get("scope") or {}
    if overview_scope.get("label") != "全版本" or overview_scope.get("active_execution_version") != active_execution_version:
        errors.append("总览 scope 必须标识全版本及当前执行版本")
    overview_stats = overview.get("stats") or {}
    portfolio_versions = (portfolio.get("versions") or [])
    if overview_stats.get("versions") != len(portfolio_versions):
        errors.append("总览版本统计必须覆盖全部版本组合")
    if overview_stats.get("features") != len(project_features):
        errors.append("总览功能统计必须覆盖项目功能浏览目录")
    progress = overview.get("development_progress") or {}
    progress_counts = progress.get("counts") or {}
    progress_items = progress.get("items") or []
    required_progress_statuses = {
        "not_started", "implementing", "local_verified", "staging_verified", "released", "unknown",
    }
    if set(progress_counts) != required_progress_statuses:
        errors.append("总览交付进度状态不完整")
    if sum(value for value in progress_counts.values() if isinstance(value, int)) != len(payload.get("features", [])):
        errors.append("总览交付进度计数必须与当前版本功能数一致")
    if len(progress_items) != len(payload.get("features", [])):
        errors.append("总览交付进度必须为每个当前版本功能保留派生依据")
    for item in progress_items:
        if item.get("status") not in required_progress_statuses or not item.get("basis") or len(item.get("sources") or []) < 2:
            errors.append(f"总览交付进度缺少状态、依据或双来源：{item.get('feature_id', '')}")
    if workbench.get("active_execution_version") != active_execution_version:
        errors.append("工作台执行版本必须等于项目 current_version")
    if portfolio.get("active_execution_version") != active_execution_version:
        errors.append("跨版本组合层不得改变当前执行版本")
    portfolio_ids = [str(item.get("id", "")) for item in portfolio.get("versions") or []]
    if len(portfolio_ids) != len(set(portfolio_ids)) or not portfolio_ids:
        errors.append("跨版本组合层缺少稳定且唯一的版本 ID")
    active_features = {str(item.get("id", "")) for item in payload.get("features", [])}
    project_feature_ids = [str(item.get("id", "")) for item in project_features]
    if len(project_feature_ids) != len(set(project_feature_ids)) or any(not item for item in project_feature_ids):
        errors.append("项目功能浏览目录缺少稳定且唯一的功能 ID")
    portfolio_feature_ids: set[str] = set()
    for version in portfolio.get("versions") or []:
        version_id = str(version.get("id", ""))
        if not version.get("sources"):
            errors.append(f"跨版本组合层缺少版本来源：{version_id}")
        for feature in version.get("features") or []:
            portfolio_feature_ids.add(str(feature.get("id", "")))
            if feature.get("version") != version_id or not feature.get("path") or not feature.get("sources"):
                errors.append(f"跨版本功能摘要缺少版本、路径或来源：{feature.get('id', '')}")
            if version_id != active_execution_version and feature.get("id") in active_features:
                errors.append(f"非执行版本功能进入当前执行 features：{feature.get('id', '')}")
            if feature.get("verification") == "passed":
                errors.append(f"跨版本功能不能从活动证据推断为已通过：{feature.get('id', '')}")
    if not portfolio_feature_ids.issubset(set(project_feature_ids)):
        errors.append("项目功能浏览目录必须覆盖跨版本功能摘要")
    for feature in project_features:
        feature_id = str(feature.get("id", ""))
        version_id = str(feature.get("version", ""))
        path = str(feature.get("path", ""))
        if not version_id or not path or not browser_doc_path(docs, path) or not (docs / path).is_file():
            errors.append(f"项目功能浏览目录缺少版本或真实文档路径：{feature_id}")
        if version_id != active_execution_version:
            if feature_id in active_features:
                errors.append(f"历史功能错误进入当前执行 features：{feature_id}")
            if feature.get("verification") == "passed" or feature.get("implementation") in {"implemented", "released"}:
                errors.append(f"历史功能不能继承当前版本实现或证据结论：{feature_id}")
    reader = (payload.get("views") or {}).get("reader") or {}
    navigation = reader.get("navigation") or {}
    modes = navigation.get("modes") or []
    if [item.get("id") for item in modes] != ["project", "version", "path"]:
        errors.append("阅读语义导航必须提供项目视角、按版本和原始目录")
    known_document_paths = {str(item.get("path", "")) for item in payload.get("documents", [])}
    for mode in modes:
        if mode.get("id") == "path":
            continue
        scoped_paths: list[str] = []
        for group in mode.get("groups") or []:
            for path in group.get("document_paths") or []:
                if not isinstance(path, str) or not path or path not in known_document_paths:
                    errors.append(f"阅读语义导航包含无效文档路径：{mode.get('id', '')}")
                else:
                    scoped_paths.append(path)
        if len(scoped_paths) != len(set(scoped_paths)):
            errors.append(f"阅读语义导航重复引用同一文档：{mode.get('id', '')}")
    document_paths = set()
    for document in payload.get("documents", []):
        relative = str(document.get("path", ""))
        path = browser_doc_path(docs, relative)
        if not path or not path.is_file():
            errors.append(f"工作台文档来源不存在：{relative}")
        else:
            document_paths.add(relative)
        content_digest = str(document.get("content_digest", ""))
        if not re.fullmatch(r"sha256:[0-9a-f]{64}", content_digest):
            errors.append(f"阅读文档缺少内容摘要：{relative}")
        sections = document.get("sections") or []
        section_ids = {str(item.get("id", "")) for item in sections if item.get("id")}
        if len(section_ids) != len(sections):
            errors.append(f"阅读章节 ID 缺失或重复：{relative}")
        previous_start = 0
        for section in sections:
            if not str(section.get("title", "")).strip() or int(section.get("level", 0) or 0) not in {1, 2, 3, 4, 5, 6}:
                errors.append(f"阅读章节信息无效：{relative}/{section.get('id', '')}")
            line_start = int(section.get("line_start", 0) or 0)
            line_end = int(section.get("line_end", 0) or 0)
            if line_start < 1 or line_end < line_start or line_end > int(document.get("line_count", 0) or 0):
                errors.append(f"阅读章节行范围无效：{relative}/{section.get('id', '')}")
            if line_start < previous_start:
                errors.append(f"阅读章节顺序无效：{relative}/{section.get('id', '')}")
            previous_start = line_start
    directory_ids = {str(item.get("id", "")) for item in payload.get("directories", [])}
    for directory in payload.get("directories", []):
        relative = str(directory.get("path", ""))
        path = browser_doc_path(docs, relative)
        if not path or not path.is_dir():
            errors.append(f"工作台目录来源不存在：{relative}")
        readme = str(directory.get("readme_path", ""))
        if readme and (not browser_doc_path(docs, readme) or not (docs / readme).is_file()):
            errors.append(f"工作台目录 README 来源不存在：{readme}")
        for child_id in directory.get("child_ids", []) or []:
            if str(child_id) not in directory_ids:
                errors.append(f"工作台目录引用未知子目录：{relative} -> {child_id}")
    for source_path in sorted(set(browser_source_paths(payload))):
        path = browser_doc_path(docs, source_path)
        if not path or not path.exists():
            errors.append(f"工作台派生对象引用不存在的权威来源：{source_path}")
    feature_ids = set(project_feature_ids)
    for timeline in (payload.get("views") or {}).get("timelines", []):
        if str(timeline.get("feature_id", "")) not in feature_ids:
            errors.append(f"功能时间线引用未知功能：{timeline.get('feature_id', '')}")
    timeline_feature_ids = {str(item.get("feature_id", "")) for item in (payload.get("views") or {}).get("timelines", [])}
    if timeline_feature_ids != feature_ids:
        errors.append("功能时间线必须覆盖项目功能浏览目录")
    for timeline in (payload.get("views") or {}).get("timelines", []):
        feature_id = str(timeline.get("feature_id", ""))
        feature = next((item for item in project_features if str(item.get("id", "")) == feature_id), {})
        if feature and str(timeline.get("version", "")) != str(feature.get("version", "")):
            errors.append(f"功能时间线版本与项目功能目录不一致：{feature_id}")
        if feature and str(feature.get("version", "")) != active_execution_version:
            if timeline.get("current_gate") in {"ready", "blocked"}:
                errors.append(f"历史功能时间线不能使用当前执行门禁：{feature_id}")
            if timeline.get("evidence_freshness") not in {"", "unknown", None}:
                errors.append(f"历史功能时间线不能使用当前版本证据新鲜度：{feature_id}")
    evolution = (payload.get("views") or {}).get("evolution") or {}
    evolution_status = str(evolution.get("status", ""))
    if evolution_status not in {"ready", "blocked", "unknown"}:
        errors.append(f"功能演进状态无效：{evolution_status}")
    if evolution_status == "ready" and evolution.get("findings"):
        errors.append("功能演进错误标记为已就绪")
    evolution_versions = evolution.get("versions") or []
    evolution_tracks = evolution.get("tracks") or []
    evolution_milestones = evolution.get("milestones") or []
    evolution_relations = evolution.get("relationships") or []
    version_ids = {str(item.get("id", "")) for item in evolution_versions if item.get("id")}
    track_ids = {str(item.get("id", "")) for item in evolution_tracks if item.get("id")}
    milestone_ids = {str(item.get("id", "")) for item in evolution_milestones if item.get("id")}
    if len(version_ids) != len(evolution_versions):
        errors.append("功能演进版本 ID 缺失或重复")
    if len(track_ids) != len(evolution_tracks):
        errors.append("功能演进能力主线 ID 缺失或重复")
    if len(milestone_ids) != len(evolution_milestones):
        errors.append("功能演进里程碑 ID 缺失或重复")
    for item in evolution_versions + evolution_milestones + evolution_relations:
        if not item.get("sources") or not any(source.get("source_path") for source in item.get("sources") or []):
            errors.append(f"功能演进对象缺少权威来源：{item.get('id', '')}")
    for milestone in evolution_milestones:
        if milestone.get("track_id") not in track_ids:
            errors.append(f"功能演进里程碑引用未知能力主线：{milestone.get('id', '')}")
        if not milestone.get("stage_keys") or not milestone.get("planning_status"):
            errors.append(f"功能演进里程碑缺少阶段或规划状态：{milestone.get('id', '')}")
    feature_track_ids = {
        str(item.get("evolution_track", "")).strip().upper()
        for item in project_features
        if str(item.get("evolution_track", "")).strip().lower() not in {"", "none"}
    }
    for track_id in sorted(feature_track_ids - track_ids):
        errors.append(f"功能引用了未登记的能力主线：{track_id}")
    known_evolution_ids = version_ids | milestone_ids
    allowed_relation_types = {"compatible", "migration", "deprecation", "replacement"}
    for relation in evolution_relations:
        if relation.get("type") not in allowed_relation_types:
            errors.append(f"功能演进关系类型无效：{relation.get('id', '')}")
        if relation.get("from") not in known_evolution_ids:
            errors.append(f"功能演进关系引用未知来源对象：{relation.get('id', '')}")
        if relation.get("to") and relation.get("to") not in known_evolution_ids:
            errors.append(f"功能演进关系引用未知目标对象：{relation.get('id', '')}")
    html_text = render_browser_html(config)
    required_markers = [
        'data-view="workbench"',
        'data-view="overview"',
        'data-view="reader"',
        'data-view="map"',
        'data-view="evolution"',
        'data-view="timeline"',
        "function readHash",
        "function updateHash",
        "function renderMarkdown",
        "function collectMarkdownReferences",
        "function parseMarkdownList",
        "function markdownTableCells",
        "function markdownLink",
        "function documentMatchLocation",
        "function restoreReaderPosition",
        "function readerPositionKey",
        "function readerContext",
        "function renderTree",
        "reader-nav-mode",
        "data-reader-nav-mode",
        "function renderWorkbench",
        "function featureCatalog",
        "project_features",
        "version_portfolio",
        "data-workbench-scope",
        "data-portfolio-feature",
        "版本功能",
        "项目功能浏览",
        "workbenchProjectFeature",
        "active_execution_version",
        "reader_mode",
        "scope:params.get",
        "function renderSearch",
        "function renderArchitectureOverview",
        "function orderedGraphNodes",
        "function renderProductArchitectureMap",
        "function renderCoreFlowMap",
        "function renderVersionRoadmapMap",
        "function renderDataDomainsMap",
        "function renderDeliveryTraceMap",
        "function renderRiskHotspotsMap",
        "function sourceAttributes",
        "function evolutionWarning",
        "function setEvolutionFocus",
        "evolution-matrix",
        "data-evolution-cell",
        "function renderVerificationPanel",
        "当前交付进度",
        "点击步骤返回权威来源",
        "打开 Markdown 原文",
        "download>下载 Markdown",
        'aria-label="关闭文档目录"',
        'aria-label="关闭阅读辅助"',
    ]
    for marker in required_markers:
        if marker not in html_text:
            errors.append(f"工作台交互契约缺少实现标记：{marker}")
    map_meta_position = html_text.find("const MAP_META")
    init_position = html_text.rfind("\n    init();")
    if map_meta_position < 0 or init_position < map_meta_position:
        errors.append("工作台必须在图谱元数据和全部呈现器定义完成后初始化")
    return sorted(set(errors))


def collect_checks(root: Path, config: dict, check_derived: bool = True) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    warnings: list[str] = []
    docs = docs_root(root, config)
    if config.get("tool_version") != TOOL_VERSION:
        warnings.append(f"项目工具版本 {config.get('tool_version', '缺失')} 与检查器 {TOOL_VERSION} 不一致，请运行 upgrade")
    if config.get("language") != "zh-CN":
        warnings.append("项目未声明 language=zh-CN")
    if not docs.exists():
        return [f"文档根目录不存在：{docs}"], warnings
    values = values_for(config)
    for item in profile_documents(str(config["profile"])):
        relative = rendered_profile_path(item, values)
        path = docs / relative
        if not path.exists():
            errors.append(f"缺少 {config['profile']} Profile 必需文件：{relative}")
            continue
        if path.suffix != ".md" or item.get("generated"):
            continue
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        for key in ["doc_id", "status", "owner", "updated", "authority"]:
            if not meta.get(key):
                errors.append(f"治理文档缺少 front matter 字段 {key}：{path}")
        if not re.search(r"^#\s+\S", text, re.MULTILINE):
            errors.append(f"治理文档缺少 H1：{path}")
        headings = [re.sub(r"^#{1,6}\s+", "", line).strip() for line in text.splitlines() if re.match(r"^#{1,6}\s+", line)]
        for section in item.get("sections", []):
            title = str(section.get("title", "")) if isinstance(section, dict) else str(section)
            if title and not any(title in heading for heading in headings):
                errors.append(f"治理文档缺少 Profile 必备章节“{title}”：{path}")

    markdown_files = sorted(docs.rglob("*.md"))
    errors.extend(collect_link_errors(markdown_files))
    warnings.extend(english_only_heading_warnings(markdown_files))
    ids: dict[str, Path] = {}
    for path in markdown_files:
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        document_id = meta.get("id") or meta.get("doc_id")
        if document_id:
            if document_id in ids:
                errors.append(f"稳定 ID 重复：{document_id}：{ids[document_id]} 与 {path}")
            ids[document_id] = path
        if "/99-历史归档/" not in path.as_posix() and PLACEHOLDER_RE.search(text):
            warnings.append(f"仍有待决占位：{path}")

    feature_pattern = re.compile(rf"^{re.escape(config['project_code'])}-FR-(\d{{3}})$")
    known_requirements: set[str] = set()
    requirement_id_pattern = re.compile(rf"^{re.escape(config['project_code'])}-(FR|NFR|RG)-\d{{3}}$")
    for item in requirement_records(root, config):
        requirement_id = str(item.get("id", ""))
        if not requirement_id_pattern.fullmatch(requirement_id):
            errors.append(f"需求 ID 无效：{requirement_id or '空值'}")
        if requirement_id in known_requirements:
            errors.append(f"需求 ID 重复：{requirement_id}")
        source_path, _ = normalize_doc_source(root, config, item.get("source", ""))
        if not source_path:
            errors.append(f"需求权威来源不可定位：{requirement_id or '空值'} -> {item.get('source', '缺失')}")
        known_requirements.add(requirement_id)

    adr_status_by_id = adr_statuses(root, config)
    feature_related: set[Path] = set()
    for record in feature_documents(root, config):
        path = record["path"]
        feature_related.add(path)
        text = record["text"]
        meta = record["meta"]
        if not feature_pattern.fullmatch(meta.get("id", "")):
            errors.append(f"功能 ID 无效：{path}")
        if meta.get("version") != str(config["current_version"]):
            errors.append(f"功能版本与当前版本不一致：{path}")
        if meta.get("status") not in STATUSES:
            errors.append(f"功能状态无效：{path}：{meta.get('status', '缺失')}")
        if meta.get("risk") not in RISKS:
            errors.append(f"功能风险等级无效：{path}：{meta.get('risk', '缺失')}")
        evolution_track = meta.get("evolution_track", "none")
        if evolution_track not in {"", "none"} and not re.fullmatch(r"TRACK-[A-Z0-9][A-Z0-9-]*", evolution_track):
            errors.append(f"功能能力主线 ID 无效：{path}：{evolution_track}")
        for heading in FEATURE_HEADINGS:
            if heading not in text:
                errors.append(f"功能文档缺少章节：{path}：{heading}")
        if not AC_ROW_RE.search(text):
            errors.append(f"功能文档没有 AC 行：{path}")
        errors.extend(validate_feature_design_depth(record))
        for requirement_id in list_field(meta.get("requirements", "")):
            if requirement_id not in known_requirements:
                errors.append(f"功能引用未知需求：{meta.get('id')} -> {requirement_id}")
        for decision_id in list_field(meta.get("decisions", "")):
            if not decision_id.startswith("ADR-"):
                continue
            adr_status = adr_status_by_id.get(decision_id)
            if not adr_status:
                errors.append(f"功能引用未知 ADR：{meta.get('id')} -> {decision_id}")
            elif adr_status != "accepted":
                errors.append(f"功能依赖的 ADR 尚未接受：{meta.get('id')} -> {decision_id}：{adr_status}")
        allowed_paths = implementation_points_from_text(text)
        forbidden_paths = normalize_goal_paths(meta.get("forbidden_paths", ""))
        for forbidden_path in forbidden_paths:
            if not valid_goal_path(forbidden_path):
                errors.append(f"功能禁止路径格式无效：{meta.get('id')} -> {forbidden_path}")
        for allowed_path, forbidden_path in goal_path_conflicts(allowed_paths, forbidden_paths):
            errors.append(f"功能允许路径与禁止路径冲突：{meta.get('id')} -> {allowed_path} / {forbidden_path}")
        if meta.get("risk") == "high":
            design = path.with_name(path.stem + "-技术设计.md")
            if not design.exists():
                errors.append(f"高风险功能缺少独立技术设计：{design}")
            else:
                feature_related.add(design)
                design_meta = parse_frontmatter(design.read_text(encoding="utf-8"))
                if design_meta.get("feature_id") != meta.get("id"):
                    errors.append(f"技术设计未绑定正确功能：{design}")
                if design_meta.get("status") not in STATUSES:
                    errors.append(f"技术设计状态无效：{design}")

    for case in e2e_documents(root, config):
        for heading in missing_headings(case["text"], ["验收目标", "前置条件与夹具", "执行步骤", "副作用与清理", "自动化入口与证据"]):
            errors.append(f"E2E 用例缺少章节“{heading}”：{case['path']}")
        if str(case["meta"].get("version", "")) != str(config["current_version"]):
            continue
        for requirement_id in list_field(case["meta"].get("requirements", "")):
            if requirement_id not in known_requirements:
                errors.append(f"E2E 用例引用未知需求：{case['meta'].get('id')} -> {requirement_id}")

    for path in future_version_documents(root, config):
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        if meta.get("status") not in {"planning", "draft", "ready", "deprecated"}:
            errors.append(f"后续版本状态无效：{path}")
        for heading in missing_headings(text, ["版本定位", "目标与成功标准", "包含范围", "不做范围", "能力与需求候选", "跨版本依赖", "架构、API 与数据影响", "风险与调研", "进入开发门禁"]):
            errors.append(f"后续版本规划缺少章节“{heading}”：{path}")

    current_architecture = docs / "04-技术架构" / "当前版本"
    if current_architecture.exists():
        for path in sorted(current_architecture.glob("*.md")):
            text = path.read_text(encoding="utf-8")
            meta = parse_frontmatter(text)
            if not meta.get("spec_id"):
                continue
            for heading in missing_headings(text, ["目标与职责", "对象与所有权", "格式、接口或状态契约", "执行流程", "安全、并发与失败处理", "版本、兼容与回滚", "可观测性", "验收与证据"]):
                errors.append(f"架构专项缺少章节“{heading}”：{path}")

    for path in sorted((docs / "90-参考资料").glob("*.md")) if (docs / "90-参考资料").exists() else []:
        if path.name == "README.md":
            continue
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        if meta.get("authority") != "non-authoritative":
            continue
        for heading in missing_headings(text, ["调研问题", "来源与可信度", "事实、推断与未知项", "方案比较", "对项目决策的影响", "失效条件与复核日期"]):
            errors.append(f"参考资料缺少章节“{heading}”：{path}")

    for path in sorted((docs / "99-历史归档").glob("*.md")) if (docs / "99-历史归档").exists() else []:
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        if meta.get("authority") != "historical-only":
            continue
        for heading in missing_headings(text, ["归档原因", "原权威范围", "当前替代来源", "迁移映射", "历史内容"]):
            errors.append(f"历史归档缺少章节“{heading}”：{path}")

    decision_ids: set[str] = set()
    for item in decision_records(root, config):
        decision_id = str(item.get("id", ""))
        if not re.fullmatch(r"D\d{3}", decision_id):
            errors.append(f"冻结决策 ID 无效：{decision_id or '空值'}")
        if decision_id in decision_ids:
            errors.append(f"冻结决策 ID 重复：{decision_id}")
        decision_ids.add(decision_id)
        for requirement_id in list_field(str(item.get("requirements", ""))):
            if requirement_id not in known_requirements:
                errors.append(f"冻结决策引用未知需求：{decision_id} -> {requirement_id}")

    openapi = docs / "04-技术架构" / "当前版本" / f"{config['current_version']}-openapi.yaml"
    if openapi.exists():
        content = openapi.read_text(encoding="utf-8")
        if not re.search(r"^openapi:\s*3\.", content, re.MULTILINE) or not re.search(r"^info:\s*$", content, re.MULTILINE):
            errors.append(f"OpenAPI 缺少 openapi 或 info：{openapi}")

    errors.extend(validate_specialized_document_contracts(root, config))
    errors.extend(validate_workbench_table_contracts(root, config))

    if check_derived:
        for path, expected in generated_documents(root, config).items():
            actual = path.read_text(encoding="utf-8") if path.exists() else ""
            if not path.exists() or not generated_document_is_current(root, config, path, actual, expected):
                errors.append(f"派生文档缺失或过期，请运行 index：{path}")
        errors.extend(validate_browser_contract(root, config))
    return sorted(set(errors)), sorted(set(warnings))


def stage_items(config: dict, stages: set[str]) -> list[dict]:
    return [item for item in profile_documents(str(config["profile"])) if item.get("gate") in stages]


def validate_stage_documents(root: Path, config: dict, stages: set[str], allowed: set[str]) -> list[str]:
    errors: list[str] = []
    docs = docs_root(root, config)
    values = values_for(config)
    for item in stage_items(config, stages):
        path = docs / rendered_profile_path(item, values)
        if not path.exists():
            errors.append(f"门禁文件缺失：{path}")
            continue
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        if path.suffix == ".md" and meta.get("status") not in allowed:
            errors.append(f"门禁文件状态 {meta.get('status', '缺失')!r} 不满足要求：{path}")
        if PLACEHOLDER_RE.search(text):
            errors.append(f"门禁文件仍有待决占位：{path}")
    return errors


def validate_features_ready(root: Path, config: dict, feature_id: str | None, release: bool = False) -> list[str]:
    errors: list[str] = []
    records = feature_documents(root, config)
    if feature_id:
        records = [record for record in records if record["meta"].get("id") == feature_id]
        if not records:
            return [f"找不到功能：{feature_id}"]
    elif not records:
        return ["当前版本没有功能规格"]
    allowed = RELEASE_STATUSES if release else READY_STATUSES
    for record in records:
        path = record["path"]
        text = record["text"]
        meta = record["meta"]
        feature = meta.get("id", str(path))
        if meta.get("status") not in allowed:
            errors.append(f"{feature} 状态 {meta.get('status', '缺失')!r} 不满足门禁")
        if PLACEHOLDER_RE.search(text):
            errors.append(f"{feature} 仍有待决占位")
        errors.extend(validate_feature_design_depth(record))
        main_depth = design_depth(text)
        if not main_depth["pseudocode_executable"]:
            errors.append(f"{feature} 功能主文档伪代码尚未形成可执行语义")
        rows = acceptance_rows(text)
        if not rows:
            errors.append(f"{feature} 没有验收标准")
        for row in rows:
            if len(row) < 8:
                errors.append(f"{feature}/{row[0] if row else '未知 AC'} 列数少于 8")
                continue
            for column, value in zip(["测试层", "目标资产", "执行命令"], row[4:7]):
                if incomplete(value):
                    errors.append(f"{feature}/{row[0]} 缺少{column}")
            if release and incomplete(row[7]):
                errors.append(f"{feature}/{row[0]} 缺少完成证据")
        if meta.get("risk") == "high":
            design = path.with_name(path.stem + "-技术设计.md")
            if not design.exists():
                errors.append(f"{feature} 缺少高风险技术设计")
            else:
                design_text = design.read_text(encoding="utf-8")
                design_meta = parse_frontmatter(design_text)
                if design_meta.get("status") not in allowed:
                    errors.append(f"{feature} 技术设计状态不满足门禁")
                if PLACEHOLDER_RE.search(design_text):
                    errors.append(f"{feature} 技术设计仍有待决占位")
                if not design_depth(design_text, high_risk=True)["pseudocode_executable"]:
                    errors.append(f"{feature} 高风险技术设计伪代码尚未形成可执行语义")
    return errors


def git_head(root: Path) -> str | None:
    result = subprocess.run(["git", "rev-parse", "HEAD"], cwd=root, text=True, capture_output=True, check=False)
    return result.stdout.strip() if result.returncode == 0 else None


def authority_files(root: Path, config: dict) -> list[Path]:
    docs = docs_root(root, config)
    files: list[Path] = []
    for path in sorted(docs.rglob("*")):
        if not path.is_file() or path.suffix.lower() not in {".md", ".yaml", ".yml", ".json"}:
            continue
        relative = path.relative_to(docs)
        if relative.parts[0] in {"90-参考资料", "99-历史归档"} or "报告" in relative.parts:
            continue
        content = path.read_text(encoding="utf-8")
        if GENERATED_MARKER in content[:200]:
            continue
        if path.suffix.lower() == ".md":
            authority = parse_frontmatter(content).get("authority")
            if authority in {"non-authoritative", "historical-only"}:
                continue
        files.append(path)
    return files


def authority_digest(root: Path, config: dict) -> tuple[str, int]:
    digest = hashlib.sha256()
    files = authority_files(root, config)
    docs = docs_root(root, config)
    for path in files:
        digest.update(path.relative_to(docs).as_posix().encode("utf-8"))
        digest.update(b"\0")
        digest.update(path.read_bytes())
        digest.update(b"\0")
    return f"sha256:{digest.hexdigest()}", len(files)


def parse_evidence_time(value: object, field: str, path: Path, errors: list[str]) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        errors.append(f"证据 {field} 不是 ISO-8601：{path}")
        return None
    if parsed.tzinfo is None:
        errors.append(f"证据 {field} 必须包含时区：{path}")
        return None
    normalized = parsed.astimezone(timezone.utc)
    if normalized > datetime.now(timezone.utc):
        errors.append(f"证据 {field} 位于未来：{path}")
    return normalized


def valid_sha256(value: object) -> bool:
    return bool(re.fullmatch(r"sha256:[0-9a-fA-F]{64}", str(value)))


def validate_development_details(report: dict, path: Path, errors: list[str]) -> None:
    details = report.get("details")
    if not isinstance(details, dict):
        errors.append(f"development 证据 details 必须是对象：{path}")
        return
    if details.get("clean_checkout") is not True:
        errors.append(f"development 证据未证明干净检出：{path}")
    if incomplete(str(details.get("dependency_mode", ""))):
        errors.append(f"development 证据缺少依赖运行模式：{path}")
    if not isinstance(details.get("services"), list) or any(not isinstance(item, str) or incomplete(item) for item in details.get("services", [])):
        errors.append(f"development 证据 services 必须是有效字符串数组：{path}")
    required = details.get("required_checks")
    expected = {"build", "static", "unit", "integration"}
    if not isinstance(required, list) or set(required) != expected or len(required) != len(expected):
        errors.append(f"development 证据必须声明 build、static、unit、integration 四项检查：{path}")
        return
    checks = report.get("checks", [])
    passed = {item.get("id") for item in checks if isinstance(item, dict) and item.get("result") == "passed"}
    missing = sorted(expected - passed)
    if missing:
        errors.append(f"development 必需检查未通过：{', '.join(missing)}：{path}")


def validate_e2e_details(root: Path, config: dict, report: dict, path: Path, errors: list[str]) -> None:
    details = report.get("details")
    if not isinstance(details, dict):
        errors.append(f"E2E 证据 details 必须是对象：{path}")
        return
    if report.get("environment") not in {"staging", "production-gate", "production"}:
        errors.append(f"E2E 证据环境不是发布级环境：{path}")
    if incomplete(str(details.get("dependency_mode", ""))):
        errors.append(f"E2E 证据缺少依赖运行模式：{path}")
    expected = {str(item["meta"].get("id")) for item in current_e2e_documents(root, config)}
    required = details.get("required_case_ids")
    if not isinstance(required, list) or any(not isinstance(item, str) or incomplete(item) for item in required):
        errors.append(f"E2E 证据 required_case_ids 必须是有效字符串数组：{path}")
        return
    if len(required) != len(set(required)):
        errors.append(f"E2E 证据 required_case_ids 存在重复：{path}")
    declared = set(required)
    if declared != expected:
        missing = sorted(expected - declared)
        unknown = sorted(declared - expected)
        if missing:
            errors.append(f"E2E 证据缺少当前版本必需用例：{', '.join(missing)}：{path}")
        if unknown:
            errors.append(f"E2E 证据声明未知用例：{', '.join(unknown)}：{path}")
    cases = details.get("cases")
    if not isinstance(cases, list) or not cases:
        errors.append(f"E2E 证据缺少逐用例结果：{path}")
        return
    by_id: dict[str, dict] = {}
    for case in cases:
        if not isinstance(case, dict):
            errors.append(f"E2E 用例结果必须是对象：{path}")
            continue
        case_id = str(case.get("id", ""))
        if incomplete(case_id):
            errors.append(f"E2E 用例结果缺少 ID：{path}")
            continue
        if case_id in by_id:
            errors.append(f"E2E 用例结果重复：{case_id}：{path}")
        by_id[case_id] = case
    for case_id in sorted(declared):
        case = by_id.get(case_id)
        if not case:
            errors.append(f"E2E 关键用例没有结果：{case_id}：{path}")
            continue
        if case.get("result") != "passed":
            errors.append(f"E2E 关键用例未通过：{case_id}={case.get('result', '缺失')}：{path}")
        if incomplete(str(case.get("evidence", ""))):
            errors.append(f"E2E 关键用例缺少证据：{case_id}：{path}")


def validate_performance_details(report: dict, path: Path, executed: datetime | None, errors: list[str]) -> None:
    details = report.get("details")
    if not isinstance(details, dict):
        errors.append(f"performance 证据 details 必须是对象：{path}")
        return
    if incomplete(str(details.get("load_profile_id", ""))):
        errors.append(f"performance 证据缺少负载模型 ID：{path}")
    if not valid_sha256(details.get("load_profile_digest")):
        errors.append(f"performance 负载模型摘要必须是 sha256：{path}")
    if incomplete(str(details.get("approved_by", ""))):
        errors.append(f"performance 负载模型缺少批准人：{path}")
    approved = parse_evidence_time(details.get("approved_at"), "details.approved_at", path, errors)
    if approved and executed and approved > executed:
        errors.append(f"performance 负载模型批准晚于执行时间：{path}")
    scenarios = details.get("scenarios")
    if not isinstance(scenarios, list) or not scenarios:
        errors.append(f"performance 证据缺少性能场景：{path}")
        return
    operators = {
        "lte": lambda actual, threshold: actual <= threshold,
        "gte": lambda actual, threshold: actual >= threshold,
        "lt": lambda actual, threshold: actual < threshold,
        "gt": lambda actual, threshold: actual > threshold,
        "eq": lambda actual, threshold: actual == threshold,
    }
    seen: set[str] = set()
    for scenario in scenarios:
        if not isinstance(scenario, dict):
            errors.append(f"performance 场景必须是对象：{path}")
            continue
        scenario_id = str(scenario.get("id", ""))
        if incomplete(scenario_id):
            errors.append(f"performance 场景缺少 ID：{path}")
            continue
        if scenario_id in seen:
            errors.append(f"performance 场景 ID 重复：{scenario_id}：{path}")
        seen.add(scenario_id)
        operator = str(scenario.get("operator", ""))
        threshold = scenario.get("threshold")
        actual = scenario.get("actual")
        if operator not in operators:
            errors.append(f"performance 场景比较符无效：{scenario_id}={operator!r}：{path}")
            continue
        if isinstance(threshold, bool) or not isinstance(threshold, (int, float)) or isinstance(actual, bool) or not isinstance(actual, (int, float)):
            errors.append(f"performance 场景阈值和实测值必须是数字：{scenario_id}：{path}")
            continue
        recalculated = operators[operator](actual, threshold)
        claimed = scenario.get("result")
        if claimed != ("passed" if recalculated else "failed"):
            errors.append(f"performance 场景手填结果与复算结果不一致：{scenario_id}：{path}")
        if not recalculated:
            errors.append(f"performance 场景未达到阈值：{scenario_id}：{path}")
        if incomplete(str(scenario.get("metric", ""))) or incomplete(str(scenario.get("unit", ""))) or incomplete(str(scenario.get("evidence", ""))):
            errors.append(f"performance 场景缺少指标、单位或证据：{scenario_id}：{path}")


def validate_release_details(report: dict, path: Path, selected: dict, errors: list[str]) -> None:
    details = report.get("details")
    if not isinstance(details, dict):
        errors.append(f"release 证据 details 必须是对象：{path}")
        return
    if not valid_sha256(details.get("artifact_digest")):
        errors.append(f"release 制品摘要必须是 sha256：{path}")
    for report_type, field in [("e2e", "e2e_report"), ("performance", "performance_report")]:
        if details.get(field) != selected.get(report_type):
            errors.append(f"release 证据未引用当前 {report_type} 报告：{path}")
    for field in ["migration", "backup", "recovery", "security", "smoke", "observation", "rollback"]:
        item = details.get(field)
        if not isinstance(item, dict):
            errors.append(f"release 证据缺少结构化检查项 {field}：{path}")
            continue
        status = item.get("status")
        if status == "passed":
            if incomplete(str(item.get("evidence", ""))):
                errors.append(f"release 检查项 {field} 缺少通过证据：{path}")
        elif status == "not_applicable":
            if incomplete(str(item.get("reason", ""))):
                errors.append(f"release 检查项 {field} 标记不适用但缺少原因：{path}")
        else:
            errors.append(f"release 检查项 {field} 未通过：{status or '缺失'}：{path}")


def validate_evidence_reports(root: Path, config: dict) -> list[str]:
    errors: list[str] = []
    selector_path = root / ".daoge-docs" / "evidence.json"
    if not selector_path.exists():
        return [f"缺少当前证据清单：{selector_path}"]
    selector = read_json(selector_path, "当前证据清单")
    if selector.get("version") != config["current_version"]:
        errors.append("当前证据清单版本与活动版本不一致")
    selected = selector.get("selected")
    if not isinstance(selected, dict):
        return errors + ["当前证据清单 selected 必须是对象"]
    reports: dict[str, dict] = {}
    report_paths: dict[str, Path] = {}
    executed_times: dict[str, datetime] = {}
    for evidence_type in sorted(EVIDENCE_TYPES):
        raw_path = selected.get(evidence_type)
        if not raw_path:
            errors.append(f"未选择 {evidence_type} 证据报告")
            continue
        relative = Path(str(raw_path))
        if relative.is_absolute() or ".." in relative.parts:
            errors.append(f"证据路径必须是仓库内相对路径：{raw_path}")
            continue
        path = root / relative
        if not path.exists():
            errors.append(f"证据报告不存在：{path}")
            continue
        report = read_json(path, f"{evidence_type} 证据报告")
        reports[evidence_type] = report
        report_paths[evidence_type] = path
        if report.get("schema_version") != 1:
            errors.append(f"证据 schema_version 不是 1：{path}")
        if report.get("type") != evidence_type:
            errors.append(f"证据类型不匹配：{path}")
        if report.get("version") != config["current_version"]:
            errors.append(f"证据版本不匹配：{path}")
        if report.get("result") != "passed":
            errors.append(f"证据结果不是 passed：{path}")
        for key in ["environment", "commit", "build_id", "executed_at"]:
            if incomplete(str(report.get(key, ""))):
                errors.append(f"证据缺少有效字段 {key}：{path}")
        commands = report.get("commands")
        if not isinstance(commands, list) or not commands:
            errors.append(f"证据缺少执行命令：{path}")
        else:
            for command in commands:
                if not isinstance(command, dict) or incomplete(str(command.get("command", ""))) or not isinstance(command.get("exit_code"), int):
                    errors.append(f"证据执行命令格式无效：{path}")
                elif command.get("exit_code") != 0:
                    errors.append(f"证据命令退出码非零：{command.get('command')}：{path}")
        checks = report.get("checks")
        if not isinstance(checks, list) or not checks:
            errors.append(f"证据缺少可复算检查项：{path}")
        else:
            seen_checks: set[str] = set()
            for check in checks:
                if not isinstance(check, dict) or incomplete(str(check.get("id", ""))):
                    errors.append(f"证据检查项格式无效：{path}")
                    continue
                check_id = str(check["id"])
                if check_id in seen_checks:
                    errors.append(f"证据检查项 ID 重复：{check_id}：{path}")
                seen_checks.add(check_id)
                if check.get("result") != "passed":
                    errors.append(f"证据检查项未通过：{check_id}={check.get('result', '缺失')}：{path}")
        if not isinstance(report.get("artifacts"), list) or not isinstance(report.get("residual_risks"), list):
            errors.append(f"证据 artifacts 和 residual_risks 必须是数组：{path}")
        executed = parse_evidence_time(report.get("executed_at"), "executed_at", path, errors)
        if executed:
            executed_times[evidence_type] = executed
        if evidence_type == "development":
            validate_development_details(report, path, errors)
        elif evidence_type == "e2e":
            validate_e2e_details(root, config, report, path, errors)
        elif evidence_type == "performance":
            validate_performance_details(report, path, executed, errors)
        elif evidence_type == "release":
            validate_release_details(report, path, selected, errors)
    if reports:
        commits = {str(report.get("commit")) for report in reports.values()}
        builds = {str(report.get("build_id")) for report in reports.values()}
        if len(commits) != 1:
            errors.append("四类证据未绑定同一提交")
        if len(builds) != 1:
            errors.append("四类证据未绑定同一构建")
        head = git_head(root)
        if head and len(commits) == 1:
            evidence_commit = next(iter(commits))
            if not head.startswith(evidence_commit):
                errors.append(f"证据提交与当前 Git HEAD 不一致：{evidence_commit} != {head}")
        release = reports.get("release", {})
        release_path = report_paths.get("release", selector_path)
        approval = release.get("approval")
        if not isinstance(approval, dict) or any(incomplete(str(approval.get(key, ""))) for key in ["proposal_id", "confirmed_by", "confirmed_at", "authority_digest"]):
            errors.append("发布证据缺少提案 ID、人工确认、确认时间或权威摘要")
        else:
            confirmed = parse_evidence_time(approval.get("confirmed_at"), "approval.confirmed_at", release_path, errors)
            if confirmed and executed_times and confirmed <= max(executed_times.values()):
                errors.append("发布批准时间必须晚于全部证据执行时间")
            current_digest, _ = authority_digest(root, config)
            if approval.get("authority_digest") != current_digest:
                errors.append("发布批准绑定的权威文档摘要已失效")
        if release.get("environment") not in {"staging", "production-gate", "production"}:
            errors.append("发布证据环境不是发布级环境")
    return errors


def collect_gate(
    root: Path,
    config: dict,
    stage: str,
    feature_id: str | None,
    check_derived: bool = True,
) -> tuple[list[str], list[str]]:
    errors, warnings = collect_checks(root, config, check_derived=check_derived)
    normalized = "feature-ready" if stage == "ready" else stage
    if normalized == "discovery":
        errors.extend(validate_stage_documents(root, config, {"discovery"}, READY_STATUSES))
    elif normalized == "version-ready":
        errors.extend(validate_stage_documents(root, config, {"discovery", "version-ready"}, READY_STATUSES))
        errors.extend(validate_features_ready(root, config, None))
        active_cases = current_e2e_documents(root, config)
        known_e2e_requirements = {req for case in active_cases for req in list_field(case["meta"].get("requirements", ""))}
        required = {str(item.get("id")) for item in requirement_records(root, config)}
        if config["profile"] == "strict" and not active_cases:
            errors.append("strict Profile 在版本进入开发前至少需要一个 E2E 验收用例")
        unmapped = sorted(req for req in required if req not in known_e2e_requirements)
        if config["profile"] == "strict" and unmapped:
            errors.append(f"需求尚未映射 E2E 用例：{', '.join(unmapped)}")
        for item in decision_records(root, config):
            if item.get("status") not in {"accepted", "deprecated"}:
                errors.append(f"冻结决策尚未确认：{item.get('id', '未知')}：{item.get('status', '缺失')}")
            if item.get("status") == "accepted" and (not item.get("confirmed_by") or not item.get("confirmed_at")):
                errors.append(f"已接受决策缺少确认记录：{item.get('id', '未知')}")
    elif normalized == "feature-ready":
        errors.extend(validate_features_ready(root, config, feature_id))
    elif normalized == "release":
        errors.extend(validate_stage_documents(root, config, {"discovery", "version-ready"}, READY_STATUSES))
        errors.extend(validate_stage_documents(root, config, {"release"}, READY_STATUSES))
        errors.extend(validate_features_ready(root, config, feature_id, release=True))
        checklist = docs_root(root, config) / "05-测试与发布" / "发布" / "检查清单.md"
        if checklist.exists() and re.search(r"^- \[ \]", checklist.read_text(encoding="utf-8"), re.MULTILINE):
            errors.append(f"发布清单仍有未勾选项：{checklist}")
        errors.extend(validate_evidence_reports(root, config))
    else:
        errors.append(f"未知门禁阶段：{stage}")
    return sorted(set(errors)), sorted(set(warnings))


def emit_report(errors: list[str], warnings: list[str], as_json: bool, label: str) -> int:
    payload = {"检查": label, "通过": not errors, "错误": errors, "警告": warnings}
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print(f"{label}：{'通过' if not errors else '失败'}")
        for error in errors:
            print(f"错误：{error}")
        for warning in warnings:
            print(f"警告：{warning}")
        print(f"汇总：{len(errors)} 个错误，{len(warnings)} 个警告")
    return 0 if not errors else 1


def command_index(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    generated = generate_indexes(root, config)
    return {"状态": "已重新生成派生文档", "文件": [str(path.relative_to(root)) for path in generated]}


def command_doctor(args: argparse.Namespace) -> int:
    root = project_root(args.root)
    config = load_config(root) if (root / CONFIG_NAME).exists() else None
    report = docs_doctor(root, config)
    if args.json:
        print(json.dumps(report, ensure_ascii=False, indent=2))
    else:
        print(f"DAOGE Docs 环境诊断：{'通过' if report['通过'] else '失败'}")
        runtime = report["运行时"]
        print(f"系统：{report['系统']['name']} {report['系统']['release']} ({report['系统']['machine']})")
        print(f"Python：{runtime['python']['version']}（最低 {runtime['python']['minimum']}）")
        print(f"Git：{runtime['git']['version'] or ('未找到' if not runtime['git']['available'] else '可用')}")
        stack_names = "、".join(item['name'] for item in report['技术栈候选']) or "未识别"
        print(f"技术栈候选：{stack_names}")
        for item in report["发现"]:
            print(f"{item['level'].upper()} {item['code']}：{item['message']} 修复：{item['fix']}")
    return 0 if report["通过"] else 1


def command_ci_check(args: argparse.Namespace) -> int:
    """以固定顺序运行可在 CI 中复现的文档与 Goal 基线检查。"""
    root = project_root(args.root)
    config = load_config(root)
    index_result = command_index(argparse.Namespace(root=str(root)))
    errors, warnings = collect_checks(root, config)
    browser_errors, browser_resources = browser_smoke(root, config)
    errors.extend(browser_errors)
    goals: list[dict] = []
    goals_root = root / ".daoge-docs" / "goals"
    if goals_root.is_dir():
        for directory in sorted(goals_root.iterdir()):
            manifest = directory / "goal-manifest.json"
            if not manifest.is_file():
                continue
            try:
                status = command_goal_status(
                    argparse.Namespace(goal=directory.name, read_only=True, fail_on_stale=False, root=str(root))
                )
                if isinstance(status, dict):
                    goals.append(status)
                    if status.get("状态") == "stale":
                        errors.append(f"Goal 已过期：{directory.name}：{'；'.join(status.get('过期原因', []))}")
            except DocsError as exc:
                errors.append(f"Goal 基线无效：{directory.name}：{exc}")
    payload = {
        "检查": "daoge-docs-ci",
        "通过": not errors,
        "工具版本": TOOL_VERSION,
        "派生文件": index_result["文件"],
        "工作台 Smoke 资源": browser_resources,
        "Goal": goals,
        "错误": sorted(set(errors)),
        "警告": sorted(set(warnings)),
    }
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print(f"daoge-docs-ci：{'通过' if payload['通过'] else '失败'}")
        for error in payload["错误"]:
            print(f"错误：{error}")
        for warning in payload["警告"]:
            print(f"警告：{warning}")
    return 0 if payload["通过"] else 1


def command_serve(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    port = int(args.port)
    if not 1 <= port <= 65535:
        raise DocsError("服务端口必须在 1 至 65535 之间")
    handler = partial(Utf8DocsRequestHandler, directory=str(root))
    try:
        server = ThreadingHTTPServer((args.host, port), handler)
    except OSError as exc:
        raise DocsError(f"无法启动本地文档服务：{args.host}:{port}：{exc}") from exc
    address = f"http://{args.host}:{server.server_address[1]}"
    print_result(
        {
            "状态": "本地 UTF-8 文档服务已启动",
            "地址": address,
            "工作台": f"{address}/{docs_root(root, config).relative_to(root).as_posix()}/90-参考资料/产品文档浏览器.html",
            "停止方式": "按 Ctrl+C",
        }
    )
    sys.stdout.flush()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return {"状态": "本地文档服务已停止", "地址": address}


def browser_smoke(root: Path, config: dict) -> tuple[list[str], list[str]]:
    """执行浏览器静态契约和本地 UTF-8 HTTP Smoke，供命令与门禁复用。"""
    errors = validate_browser_contract(root, config)
    docs = docs_root(root, config)
    handler = partial(QuietUtf8DocsRequestHandler, directory=str(root))
    server: ThreadingHTTPServer | None = None
    worker: threading.Thread | None = None
    checks: list[str] = []
    try:
        server = ThreadingHTTPServer(("127.0.0.1", 0), handler)
        worker = threading.Thread(target=server.serve_forever, daemon=True)
        worker.start()
        base = f"http://127.0.0.1:{server.server_address[1]}"
        relative_files = [
            docs.relative_to(root).as_posix() + "/90-参考资料/产品文档浏览器.html",
            docs.relative_to(root).as_posix() + "/90-参考资料/产品文档浏览器-文档数据.js",
        ]
        markdown = next((path for path in sorted(docs.rglob("*.md")) if path.is_file()), None)
        if markdown:
            relative_files.append(markdown.relative_to(root).as_posix())
        for relative in relative_files:
            try:
                with urlopen(f"{base}/{quote(relative)}", timeout=3) as response:
                    body = response.read()
                    content_type = response.headers.get_content_type()
                    charset = response.headers.get_content_charset()
                if not charset or charset.lower() != "utf-8":
                    errors.append(f"工作台资源未声明 UTF-8：{relative}")
                if relative.endswith(".md") and content_type != "text/markdown":
                    errors.append(f"Markdown 原文 MIME 不正确：{relative}={content_type}")
                if relative.endswith(".md"):
                    try:
                        decoded = body.decode(charset or "utf-8")
                    except UnicodeDecodeError:
                        decoded = ""
                    if not decoded or "#" not in decoded:
                        errors.append(f"Markdown 原文无法按 UTF-8 读取：{relative}")
                checks.append(relative)
            except Exception as exc:  # pragma: no cover - exercised through CLI integration
                errors.append(f"工作台资源无法通过本地服务读取：{relative}：{exc}")
    finally:
        if server:
            server.shutdown()
            server.server_close()
        if worker:
            worker.join(timeout=3)
    return sorted(set(errors)), checks


def command_browser_check(args: argparse.Namespace) -> int:
    """对派生工作台执行无外部依赖的静态与 HTTP Smoke 验收。"""
    root = project_root(args.root)
    config = load_config(root)
    errors, checks = browser_smoke(root, config)
    if errors:
        return emit_report(sorted(set(errors)), [], args.json, "browser-smoke")
    payload = {"检查": "browser-smoke", "通过": True, "资源": checks, "视图": 6, "图谱": 6}
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print("browser-smoke：通过")
        print(f"资源：{len(checks)} 个，视图：6 个，图谱：6 个")
    return 0


def command_snapshot(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    if args.version and args.version != str(config["current_version"]):
        raise DocsError("当前 V2 快照只能从活动版本生成；请先切换 current_version 后再创建快照")
    snapshot = snapshot_payload(root, config, args.commit)
    directory = snapshot_directory(root, config)
    path = directory / f"{snapshot['version']}-{snapshot['authority_digest'].split(':', 1)[-1][:16]}.json"
    if path.exists():
        existing = read_json(path, "版本快照")
        if existing.get("authority_digest") != snapshot["authority_digest"] or existing.get("source_commit") != snapshot["source_commit"]:
            raise DocsError(f"快照目标已存在但内容不一致，拒绝覆盖：{path}")
        status = "已存在，保持不可变"
    else:
        write_new(path, json.dumps(snapshot, ensure_ascii=False, indent=2) + "\n")
        status = "已创建不可变快照"
    generate_indexes(root, config)
    return {
        "状态": status,
        "快照 ID": snapshot["snapshot_id"],
        "版本": snapshot["version"],
        "权威摘要": snapshot["authority_digest"],
        "提交": snapshot["source_commit"],
        "文件": str(path.relative_to(root)),
    }


def command_authority_digest(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    digest, count = authority_digest(root, config)
    return {"权威文档摘要": digest, "纳入文件数": count}


def goal_generated_paths(root: Path, config: dict) -> set[str]:
    return {path.relative_to(root).as_posix() for path in generated_documents(root, config)}


def git_dirty_paths(root: Path, ignored_paths: Iterable[str] = ()) -> list[str]:
    result = subprocess.run(
        ["git", "-c", "core.quotepath=false", "status", "--porcelain", "--untracked-files=all"],
        cwd=root,
        text=True,
        capture_output=True,
        check=False,
    )
    if result.returncode != 0:
        return []
    ignored = {normalize_repo_path(path) for path in ignored_paths}
    paths: list[str] = []
    for line in result.stdout.splitlines():
        raw = line[3:].strip() if len(line) > 3 else ""
        path = normalize_repo_path(raw.split(" -> ", 1)[-1])
        if path and not path.startswith(".daoge-docs/goals/") and path not in ignored:
            paths.append(path)
    return sorted(set(paths))


def goal_semantic_payload(manifest: dict) -> dict:
    value = json.loads(json.dumps(manifest, ensure_ascii=False))
    for key in ["generated_at", "status", "status_checked_at", "stale_reasons", "manifest_digest"]:
        value.pop(key, None)
    return value


def goal_manifest_digest(manifest: dict) -> str:
    return canonical_digest(goal_semantic_payload(manifest))


def record_digest(value: dict, field: str) -> str:
    payload = json.loads(json.dumps(value, ensure_ascii=False))
    payload.pop(field, None)
    return canonical_digest(payload)


def goal_directory(root: Path, goal_id: str) -> Path:
    if not GOAL_ID_RE.fullmatch(goal_id):
        raise DocsError("Goal ID 必须使用 GOAL-* 格式，并且只能包含大写字母、数字和连字符")
    return root / ".daoge-docs" / "goals" / goal_id


def load_goal_manifest(root: Path, goal_id: str) -> tuple[Path, dict]:
    manifest_path = goal_directory(root, goal_id) / "goal-manifest.json"
    if not manifest_path.exists():
        raise DocsError(f"Goal 清单不存在：{goal_id}")
    manifest = read_json(manifest_path, "Goal 清单")
    if manifest.get("schema_version") != GOAL_SCHEMA_VERSION or manifest.get("goal_id") != goal_id:
        raise DocsError("Goal 清单身份或 schema_version 无效")
    if manifest.get("manifest_digest") != goal_manifest_digest(manifest):
        raise DocsError("Goal 清单语义内容已被修改，拒绝继续评估")
    return manifest_path, manifest


def goal_relative_file(root: Path, goal_id: str, relative: str, label: str) -> Path:
    if not relative or Path(relative).is_absolute() or ".." in Path(relative).parts:
        raise DocsError(f"{label}路径无效：{relative}")
    path = (root / relative).resolve()
    goal_root = goal_directory(root, goal_id).resolve()
    try:
        path.relative_to(goal_root)
    except ValueError as exc:
        raise DocsError(f"{label}超出 Goal 目录：{relative}") from exc
    return path


def validate_goal_evidence(root: Path, goal_id: str, relative: str, commit: str) -> dict:
    path = goal_relative_file(root, goal_id, relative, "Goal 证据")
    if not path.exists():
        raise DocsError(f"Goal 证据不存在：{relative}")
    report = read_json(path, "Goal 命令证据")
    if report.get("goal_id") != goal_id or report.get("commit") != commit:
        raise DocsError(f"Goal 证据身份或提交不匹配：{relative}")
    if report.get("evidence_digest") != record_digest(report, "evidence_digest"):
        raise DocsError(f"Goal 证据摘要无效：{relative}")
    if report.get("result") != "passed" or report.get("exit_code") != report.get("expected_exit_code"):
        raise DocsError(f"Goal 证据未通过：{relative}")
    return report


def validate_goal_checkpoint_chain(root: Path, manifest: dict) -> tuple[list[dict], str]:
    goal_id = str(manifest["goal_id"])
    expected_parent = str(manifest.get("source_commit", ""))
    records: list[dict] = []
    tasks = manifest.get("ordered_tasks", [])
    for index, summary in enumerate(manifest.get("checkpoints", []), start=1):
        checkpoint_id = f"CP-{index:03d}"
        if summary.get("checkpoint_id") != checkpoint_id:
            raise DocsError(f"Goal 检查点顺序无效：期望 {checkpoint_id}")
        relative = str(summary.get("record_path", ""))
        path = goal_relative_file(root, goal_id, relative, "Goal 检查点")
        if not path.exists():
            raise DocsError(f"Goal 检查点记录不存在：{relative}")
        record = read_json(path, "Goal 检查点记录")
        if record.get("checkpoint_id") != checkpoint_id or record.get("goal_id") != goal_id:
            raise DocsError(f"Goal 检查点身份无效：{relative}")
        if record.get("checkpoint_digest") != record_digest(record, "checkpoint_digest"):
            raise DocsError(f"Goal 检查点摘要无效：{relative}")
        if summary.get("checkpoint_digest") != record.get("checkpoint_digest"):
            raise DocsError(f"Goal 检查点清单摘要不匹配：{checkpoint_id}")
        if record.get("parent_commit") != expected_parent:
            raise DocsError(f"Goal 检查点父提交不连续：{checkpoint_id}")
        if record.get("authority_digest") != manifest.get("authority_digest"):
            raise DocsError(f"Goal 检查点权威摘要不匹配：{checkpoint_id}")
        task_id = str(record.get("task_id", ""))
        if index > len(tasks) or task_id != tasks[index - 1].get("task_id"):
            raise DocsError(f"Goal 检查点任务顺序不匹配：{checkpoint_id}")
        if tasks[index - 1].get("status") != "completed":
            raise DocsError(f"Goal 检查点对应任务未完成：{task_id}")
        commit = str(record.get("commit", ""))
        if not commit or commit == expected_parent:
            raise DocsError(f"Goal 检查点没有独立提交：{checkpoint_id}")
        if not git_is_ancestor(root, expected_parent, commit):
            raise DocsError(f"Goal 检查点提交不能追溯到父提交：{checkpoint_id}")
        if git_merge_commits(root, expected_parent, commit):
            raise DocsError(f"Goal 检查点包含未允许的 merge commit：{checkpoint_id}")
        actual_all_paths = git_changed_paths(root, expected_parent, commit)
        actual_managed_paths = [path for path in actual_all_paths if goal_managed_git_path(manifest, path)]
        actual_changed_paths = [path for path in actual_all_paths if path not in actual_managed_paths]
        if record.get("changed_paths") != actual_changed_paths or record.get("managed_paths", []) != actual_managed_paths:
            raise DocsError(f"Goal 检查点变更路径与 Git 不一致：{checkpoint_id}")
        task = tasks[index - 1]
        if any(not goal_path_matches(path, task.get("allowed_paths", [])) for path in actual_changed_paths):
            raise DocsError(f"Goal 检查点包含授权范围外路径：{checkpoint_id}")
        if any(goal_path_matches(path, task.get("forbidden_paths", [])) for path in actual_changed_paths):
            raise DocsError(f"Goal 检查点包含禁止路径：{checkpoint_id}")
        evidence_paths = record.get("evidence_paths", [])
        if not evidence_paths:
            raise DocsError(f"Goal 检查点缺少命令证据：{checkpoint_id}")
        command_by_id = {str(item.get("id", "")): item for item in task.get("verification_commands", [])}
        record_commands = record.get("commands", [])
        if {str(item.get("command_id", "")) for item in record_commands} != set(command_by_id):
            raise DocsError(f"Goal 检查点验证命令集合不匹配：{checkpoint_id}")
        if {str(item.get("evidence_path", "")) for item in record_commands} != {str(item) for item in evidence_paths}:
            raise DocsError(f"Goal 检查点命令与证据路径不匹配：{checkpoint_id}")
        for command_summary in record_commands:
            command_id = str(command_summary.get("command_id", ""))
            expected_command = command_by_id[command_id]
            evidence_path = str(command_summary.get("evidence_path", ""))
            report = validate_goal_evidence(root, goal_id, evidence_path, commit)
            if report.get("command_id") != command_id or report.get("command") != expected_command.get("command"):
                raise DocsError(f"Goal 检查点命令证据与清单不匹配：{checkpoint_id}/{command_id}")
            if report.get("evidence_digest") != command_summary.get("evidence_digest"):
                raise DocsError(f"Goal 检查点命令证据摘要不匹配：{checkpoint_id}/{command_id}")
        records.append(record)
        expected_parent = commit
    return records, expected_parent


def validate_goal_completion(root: Path, manifest: dict) -> dict | None:
    completion = manifest.get("completion")
    if not completion:
        return None
    relative = str(completion.get("record_path", ""))
    path = goal_relative_file(root, str(manifest["goal_id"]), relative, "Goal 完成记录")
    if not path.exists():
        raise DocsError(f"Goal 完成记录不存在：{relative}")
    record = read_json(path, "Goal 完成记录")
    if record.get("goal_id") != manifest.get("goal_id"):
        raise DocsError("Goal 完成记录身份无效")
    if record.get("completion_digest") != record_digest(record, "completion_digest"):
        raise DocsError("Goal 完成记录摘要无效")
    if completion.get("completion_digest") != record.get("completion_digest"):
        raise DocsError("Goal 完成记录与清单摘要不匹配")
    if record.get("status") != "completed" or record.get("final_commit") != completion.get("commit"):
        raise DocsError("Goal 完成记录状态或最终提交无效")
    if record.get("authority_digest") != manifest.get("authority_digest"):
        raise DocsError("Goal 完成记录权威摘要不匹配")
    evidence_paths = record.get("verification_evidence_paths", [])
    if not evidence_paths:
        raise DocsError("Goal 完成记录缺少最终验证证据")
    expected_commands = {str(item.get("id", "")): item for item in manifest.get("verification_commands", [])}
    seen_commands: set[str] = set()
    for evidence_path in evidence_paths:
        report = validate_goal_evidence(root, str(manifest["goal_id"]), str(evidence_path), str(record["final_commit"]))
        command_id = str(report.get("command_id", ""))
        expected = expected_commands.get(command_id)
        if not expected or report.get("command") != expected.get("command"):
            raise DocsError(f"Goal 最终验证命令与清单不匹配：{command_id}")
        seen_commands.add(command_id)
    if seen_commands != set(expected_commands):
        raise DocsError("Goal 完成记录未覆盖全部最终验证命令")
    return record


def git_is_ancestor(root: Path, ancestor: str, descendant: str) -> bool:
    if not ancestor or not descendant:
        return False
    result = subprocess.run(
        ["git", "merge-base", "--is-ancestor", ancestor, descendant],
        cwd=root,
        text=True,
        capture_output=True,
        check=False,
    )
    return result.returncode == 0


def git_changed_paths(root: Path, base: str, head: str) -> list[str]:
    result = subprocess.run(
        ["git", "-c", "core.quotepath=false", "diff", "--name-only", "-z", base, head],
        cwd=root,
        capture_output=True,
        check=False,
    )
    if result.returncode != 0:
        raise DocsError("无法计算 Goal 检查点的提交差异")
    return sorted({normalize_repo_path(item.decode("utf-8")) for item in result.stdout.split(b"\0") if item})


def goal_managed_git_path(manifest: dict, path: str) -> bool:
    goal_prefix = f".daoge-docs/goals/{manifest.get('goal_id', '')}/"
    normalized_path = normalize_repo_path(path)
    managed_paths = {normalize_repo_path(item) for item in manifest.get("ignored_generated_paths", [])}
    return normalized_path.startswith(goal_prefix) or normalized_path in managed_paths


def goal_commit_matches_expected(root: Path, manifest: dict, expected: str, current: str) -> bool:
    if current == expected:
        return True
    if not git_is_ancestor(root, expected, current):
        return False
    changed = git_changed_paths(root, expected, current)
    return bool(changed) and all(goal_managed_git_path(manifest, path) for path in changed)


def git_merge_commits(root: Path, base: str, head: str) -> list[str]:
    result = subprocess.run(
        ["git", "rev-list", "--merges", f"{base}..{head}"],
        cwd=root,
        text=True,
        capture_output=True,
        check=False,
    )
    if result.returncode != 0:
        raise DocsError("无法检查 Goal 检查点提交历史")
    return [line.strip() for line in result.stdout.splitlines() if line.strip()]


def goal_path_matches(path: str, allowed: Iterable[str]) -> bool:
    normalized = Path(path).as_posix().rstrip("/")
    for value in allowed:
        boundary = Path(str(value)).as_posix().rstrip("/")
        if normalized == boundary or normalized.startswith(boundary + "/"):
            return True
    return False


def next_goal_evidence_path(directory: Path, scope: str, command_id: str) -> Path:
    safe_scope = re.sub(r"[^A-Za-z0-9_-]", "-", scope)
    safe_command = re.sub(r"[^A-Za-z0-9_-]", "-", command_id)
    for attempt in range(1, 1000):
        path = directory / "evidence" / f"{safe_scope}-{safe_command}-attempt-{attempt:03d}.json"
        if not path.exists():
            return path
    raise DocsError(f"验证命令尝试次数过多：{command_id}")


def run_goal_verification(
    root: Path,
    directory: Path,
    manifest: dict,
    command: dict,
    scope: str,
    commit: str,
) -> dict:
    command_id = str(command.get("id", ""))
    command_text = str(command.get("command", "")).strip()
    cwd_value = str(command.get("cwd", "."))
    timeout_seconds = int(command.get("timeout_seconds", 900))
    expected_exit_code = int(command.get("expected_exit_code", 0))
    cwd = (root / cwd_value).resolve()
    try:
        cwd.relative_to(root)
    except ValueError as exc:
        raise DocsError(f"验证命令工作目录超出项目：{command_id}") from exc
    if not command_text or not cwd.is_dir() or timeout_seconds <= 0:
        raise DocsError(f"验证命令契约无效：{command_id}")
    started_at = now_iso()
    timed_out = False
    try:
        shell = runtime_shell()
        if os.name == "nt":
            shell_name = windows_shell()
            if not shell_name:
                raise DocsError("当前 Windows 环境没有 PowerShell；请先运行 doctor 排查。")
            invocation: object = [shell_name, "-NoProfile", "-NonInteractive", "-Command", command_text]
            run_options = {"shell": False}
        elif shell:
            invocation = command_text
            run_options = {"shell": True, "executable": shell}
            shell_name = shell
        else:
            raise DocsError("当前环境没有可用于 Goal 验证的 shell；请先运行 doctor 排查。")
        result = subprocess.run(
            invocation,
            cwd=cwd,
            text=True,
            capture_output=True,
            env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"},
            timeout=timeout_seconds,
            check=False,
            **run_options,
        )
        exit_code: int | None = result.returncode
        stdout = result.stdout
        stderr = result.stderr
    except subprocess.TimeoutExpired as exc:
        timed_out = True
        exit_code = None
        stdout = exc.stdout.decode("utf-8", errors="replace") if isinstance(exc.stdout, bytes) else (exc.stdout or "")
        stderr = exc.stderr.decode("utf-8", errors="replace") if isinstance(exc.stderr, bytes) else (exc.stderr or "")
    evidence_path = next_goal_evidence_path(directory, scope, command_id)
    passed = not timed_out and exit_code == expected_exit_code
    evidence = {
        "schema_version": 1,
        "goal_id": manifest["goal_id"],
        "scope": scope,
        "command_id": command_id,
        "command": command_text,
        "cwd": cwd_value,
        "timeout_seconds": timeout_seconds,
        "expected_exit_code": expected_exit_code,
        "exit_code": exit_code,
        "result": "passed" if passed else ("timed_out" if timed_out else "failed"),
        "environment": "local",
        "shell": shell_name,
        "python_version": sys.version.split()[0],
        "commit": commit,
        "authority_digest": manifest["authority_digest"],
        "started_at": started_at,
        "completed_at": now_iso(),
        "stdout_digest": canonical_digest(stdout),
        "stderr_digest": canonical_digest(stderr),
        "stdout_bytes": len(stdout.encode("utf-8")),
        "stderr_bytes": len(stderr.encode("utf-8")),
        "tool_version": TOOL_VERSION,
    }
    evidence["evidence_digest"] = record_digest(evidence, "evidence_digest")
    write_json(evidence_path, evidence)
    evidence["path"] = str(evidence_path.relative_to(root))
    return evidence


def next_goal_id(root: Path, version: str) -> str:
    base = root / ".daoge-docs" / "goals"
    pattern = re.compile(rf"GOAL-{re.escape(version.upper())}-(\d{{3}})$")
    numbers = []
    if base.exists():
        for path in base.iterdir():
            match = pattern.fullmatch(path.name)
            if match:
                numbers.append(int(match.group(1)))
    return f"GOAL-{version.upper()}-{max(numbers, default=0) + 1:03d}"


def selected_feature_ids(values: list[str]) -> list[str]:
    selected = sorted({item.strip().upper() for value in values for item in value.split(",") if item.strip()})
    if not selected:
        raise DocsError("至少使用一次 --feature 选择当前版本功能")
    return selected


def goal_target_config(config: dict, version: str | None = None) -> dict:
    """Return an in-memory config scoped to a Goal target version."""
    selected = str(version or config["current_version"]).strip().upper()
    if not re.fullmatch(r"V\d+", selected):
        raise DocsError(f"Goal 目标版本格式无效：{selected or '缺失'}")
    target = dict(config)
    target["current_version"] = selected
    return target


def valid_goal_path(path: str) -> bool:
    if not path or path.startswith(("/", "~")) or "\\" in path or any(char in path for char in "*?[]{}$"):
        return False
    parts = Path(path).parts
    return len(parts) >= 2 and all(part not in {"", ".", ".."} for part in parts)


def ordered_goal_features(features: list[dict]) -> tuple[list[dict], list[str]]:
    by_id = {str(item.get("id", "")): item for item in features}
    dependencies = {
        feature_id: sorted({dependency for dependency in item.get("dependencies", []) if dependency in by_id})
        for feature_id, item in by_id.items()
    }
    incoming = {feature_id: len(values) for feature_id, values in dependencies.items()}
    dependents: dict[str, list[str]] = {feature_id: [] for feature_id in by_id}
    for feature_id, values in dependencies.items():
        for dependency in values:
            dependents[dependency].append(feature_id)
    ready = sorted(feature_id for feature_id, count in incoming.items() if count == 0)
    ordered: list[str] = []
    while ready:
        feature_id = ready.pop(0)
        ordered.append(feature_id)
        for dependent in sorted(dependents[feature_id]):
            incoming[dependent] -= 1
            if incoming[dependent] == 0:
                ready.append(dependent)
                ready.sort()
    cycles = sorted(set(by_id) - set(ordered))
    ordered.extend(cycles)
    return [by_id[feature_id] for feature_id in ordered], cycles


def normalize_goal_issue(root: Path, value: str) -> str:
    return value.replace(str(root), ".")


def command_prepare_goal(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    target_config = goal_target_config(config, getattr(args, "version", None))
    target_version = str(target_config["current_version"])
    generated_paths = goal_generated_paths(root, config)
    dirty_paths = git_dirty_paths(root, generated_paths)
    # Keep the active execution browser on the project's current version. A
    # historical Goal uses an in-memory target projection instead.
    generate_indexes(root, config)
    payload = browser_payload(root, target_config)
    requested = selected_feature_ids(args.feature)
    feature_by_id = {str(item.get("id", "")): item for item in payload.get("features", [])}
    missing = [feature_id for feature_id in requested if feature_id not in feature_by_id]
    if missing:
        raise DocsError(f"当前版本找不到功能：{', '.join(missing)}")
    selected_features, cycles = ordered_goal_features([feature_by_id[feature_id] for feature_id in requested])
    packet_by_feature = {str(item.get("feature_id", "")): item for item in payload.get("task_packets", [])}
    goal_id = args.goal_id.strip().upper() if args.goal_id else next_goal_id(root, target_version)
    directory = goal_directory(root, goal_id)
    manifest_path = directory / "goal-manifest.json"
    if manifest_path.exists() or directory.exists():
        raise DocsError(f"Goal ID 已存在，拒绝覆盖：{goal_id}")

    blocking: list[dict] = []

    def block(code: str, reason: str, feature_id: str = "") -> None:
        item = {"code": code, "reason": normalize_goal_issue(root, reason)}
        if feature_id:
            item["feature_id"] = feature_id
        if item not in blocking:
            blocking.append(item)

    derived_checks = target_version == str(config["current_version"])
    version_errors, _ = collect_gate(root, target_config, "version-ready", None, check_derived=derived_checks)
    for error in version_errors:
        block("VERSION_READY", error)
    for feature_id in requested:
        feature_errors, _ = collect_gate(root, target_config, "feature-ready", feature_id, check_derived=derived_checks)
        for error in feature_errors:
            block("FEATURE_READY", error, feature_id)
    source_commit = git_head(root) or ""
    if not source_commit:
        block("SOURCE_COMMIT", "当前项目没有可解析的 Git HEAD")
    if dirty_paths:
        block("WORKTREE_DIRTY", f"工作区存在未提交变化：{', '.join(dirty_paths)}")
    if cycles:
        block("TASK_CYCLE", f"功能依赖形成循环：{', '.join(cycles)}")

    tasks: list[dict] = []
    all_commands: list[dict] = []
    evidence_types = {"development"}
    for sequence, feature in enumerate(selected_features, start=1):
        feature_id = str(feature["id"])
        packet = packet_by_feature.get(feature_id, {})
        task_id = f"TASK-{feature_id}"
        allowed_paths = sorted({path for path in packet.get("implementation_points", []) if valid_goal_path(path)})
        declared_forbidden_paths = sorted(set(packet.get("forbidden_paths", [])))
        invalid_forbidden_paths = [path for path in declared_forbidden_paths if not valid_goal_path(path)]
        if invalid_forbidden_paths:
            block("FORBIDDEN_PATHS", "功能声明了无效的禁止修改路径：" + ", ".join(invalid_forbidden_paths), feature_id)
        path_conflicts = goal_path_conflicts(allowed_paths, declared_forbidden_paths)
        if path_conflicts:
            block(
                "PATH_CONFLICT",
                "允许路径与禁止路径重叠：" + ", ".join(f"{left} / {right}" for left, right in path_conflicts),
                feature_id,
            )
        if not allowed_paths:
            block("ALLOWED_PATHS", "功能未声明可解析且边界明确的工程落点", feature_id)
        acceptance = packet.get("acceptance", [])
        if not acceptance:
            block("AC_MISSING", "功能没有可解析的验收项", feature_id)
        branches = packet.get("branches", [])
        if not branches:
            block("BRANCH_MISSING", "功能没有可追踪的稳定分支", feature_id)
        command_values = sorted({str(item.get("command", "")).strip() for item in acceptance if str(item.get("command", "")).strip()})
        command_values = [command for command in command_values if not incomplete(command) and not re.search(r"待|已确认|证据", command)]
        if not command_values:
            block("VERIFY_COMMAND", "功能没有可执行的验证命令", feature_id)
        commands = []
        for index, command in enumerate(command_values, start=1):
            command_item = {
                "id": f"VERIFY-{feature_id}-{index:02d}",
                "command": command,
                "cwd": ".",
                "timeout_seconds": 900,
                "expected_exit_code": 0,
                "evidence_path": f".daoge-docs/goals/{goal_id}/evidence/{task_id}-{index:02d}.json",
            }
            commands.append(command_item)
            all_commands.append(command_item)
        task_evidence_types = {"development"}
        for item in acceptance:
            layer = str(item.get("test_layer", "")).lower()
            if "e2e" in layer:
                task_evidence_types.add("e2e")
            if "性能" in layer or "performance" in layer:
                task_evidence_types.add("performance")
            if "安全" in layer or "发布" in layer or "security" in layer or "release" in layer:
                task_evidence_types.add("release")
        evidence_types.update(task_evidence_types)
        internal_dependencies = sorted({f"TASK-{dependency}" for dependency in feature.get("dependencies", []) if dependency in requested})
        external_dependencies = sorted({dependency for dependency in feature.get("dependencies", []) if dependency not in requested})
        tasks.append(
            {
                "task_id": task_id,
                "title": feature.get("title", feature_id),
                "objective": packet.get("scope", {}).get("summary") or feature.get("summary", ""),
                "status": "pending",
                "sequence": sequence,
                "dependencies": internal_dependencies,
                "external_dependencies": external_dependencies,
                "inputs": [
                    {
                        "source_path": source_path,
                        "source_section": "功能规格" if source_path == feature.get("path") else "技术设计",
                        "source_id": feature_id,
                    }
                    for source_path in packet.get("source_paths", [])
                    if source_path
                ],
                "requirement_ids": sorted(set(packet.get("requirements", []))),
                "acceptance_ids": [f"{feature_id}:{item.get('id', '')}" for item in acceptance if item.get("id")],
                "branch_ids": [item.get("id", "") for item in branches if item.get("id")],
                "allowed_paths": allowed_paths,
                "forbidden_paths": declared_forbidden_paths,
                "implementation_constraints": [item.get("summary", "") for item in branches if item.get("summary")],
                "verification_commands": commands,
                "evidence_requirements": sorted(task_evidence_types),
                "completion_conditions": [
                    condition
                    for item in acceptance
                    if (condition := item.get("then") or item.get("when") or item.get("given"))
                ],
                "stop_conditions": ["权威摘要、Git 基线、AC、稳定分支或允许路径发生变化时立即停止。"],
                "checkpoint_policy": "仅在本任务全部验证命令通过后建立原子检查点。",
                "parallel_eligible": False,
            }
        )

    authority_digest_value = str(payload.get("authority_digest", ""))
    if not authority_digest_value:
        block("AUTHORITY_DIGEST", "未生成 authority digest")
    blocking.sort(key=lambda item: (item["code"], item.get("feature_id", ""), item["reason"]))
    objective = args.objective.strip() if args.objective else f"完成 {', '.join(requested)} 并取得开发级机器证据"
    manifest = {
        "schema_version": GOAL_SCHEMA_VERSION,
        "goal_id": goal_id,
        "status": "blocked" if blocking else "ready",
        "objective": objective,
        "version": target_version,
        "current_execution_version": str(config["current_version"]),
        "feature_ids": requested,
        "requirement_ids": sorted({value for task in tasks for value in task["requirement_ids"]}),
        "decision_ids": sorted({value for feature in selected_features for value in feature.get("decisions", [])}),
        "scope": [{"feature_id": feature["id"], "summary": feature.get("summary", "")} for feature in selected_features],
        "non_goals": sorted({value for feature in selected_features for value in feature.get("non_goals", [])}),
        "allowed_paths": sorted({value for task in tasks for value in task["allowed_paths"]}),
        "forbidden_paths": sorted({value for task in tasks for value in task["forbidden_paths"]}),
        "forbidden_actions": sorted({value for feature_id in requested for value in packet_by_feature.get(feature_id, {}).get("forbidden_actions", [])}),
        "authority_digest": authority_digest_value,
        "source_commit": source_commit,
        "tool_version": TOOL_VERSION,
        "browser_schema_version": payload.get("schema_version"),
        "ignored_generated_paths": sorted(generated_paths),
        "selection_digest": canonical_digest({"version": target_version, "features": requested}),
        "ordered_tasks": tasks,
        "integration_order": [task["task_id"] for task in tasks],
        "execution_policy": "serial",
        "verification_commands": all_commands,
        "evidence_requirements": sorted(evidence_types),
        "stop_conditions": [
            "authority digest 与清单不一致时停止。",
            "HEAD 与 source_commit 不一致且没有受控检查点时停止。",
            "出现清单外路径、未登记提交、权威冲突或新业务决策时停止。",
            "需要破坏性迁移、不可逆删除或未批准外部副作用时停止。",
            "验证失败且修复需要改变 AC、设计或非目标时停止。",
        ],
        "blocking_findings": blocking,
        "checkpoints": [],
        "generated_at": now_iso(),
        "status_checked_at": now_iso(),
        "stale_reasons": [],
    }
    manifest["manifest_digest"] = goal_manifest_digest(manifest)
    directory.mkdir(parents=True, exist_ok=False)
    (directory / "checkpoints").mkdir()
    (directory / "evidence").mkdir()
    write_json(manifest_path, manifest)
    return {
        "状态": manifest["status"],
        "Goal ID": goal_id,
        "功能": requested,
        "目标版本": target_version,
        "当前执行版本": str(config["current_version"]),
        "任务数": len(tasks),
        "阻塞数": len(blocking),
        "权威摘要": authority_digest_value,
        "提交": source_commit,
        "文件": str(manifest_path.relative_to(root)),
    }


def command_goal_status(args: argparse.Namespace) -> dict | int:
    root = project_root(args.root)
    config = load_config(root)
    goal_id = args.goal.strip().upper()
    manifest_path, manifest = load_goal_manifest(root, goal_id)
    target_config = goal_target_config(config, str(manifest.get("version", "")))
    _, expected_commit = validate_goal_checkpoint_chain(root, manifest)
    completion = validate_goal_completion(root, manifest)
    current_digest = authority_digest(root, target_config)[0]
    current_commit = git_head(root) or ""
    reasons: list[str] = []
    freshness_reasons: list[str] = []
    if completion:
        if not git_is_ancestor(root, str(completion.get("final_commit", "")), current_commit):
            raise DocsError("Goal 完成记录的最终提交不在当前 Git 历史中")
        if manifest.get("authority_digest") != current_digest:
            freshness_reasons.append("当前权威已变化，完成记录作为历史证据保留")
        if manifest.get("tool_version") != TOOL_VERSION:
            freshness_reasons.append("当前工具版本已变化")
    else:
        if manifest.get("authority_digest") != current_digest:
            reasons.append("权威文档摘要已变化")
        if not manifest.get("source_commit"):
            reasons.append("清单没有绑定 source_commit")
        elif not goal_commit_matches_expected(root, manifest, expected_commit, current_commit):
            reasons.append("当前 HEAD 与最近受控检查点不一致")
        if manifest.get("tool_version") != TOOL_VERSION:
            reasons.append("DAOGE Docs 工具版本已变化")
        dirty_paths = git_dirty_paths(root, manifest.get("ignored_generated_paths", []))
        if dirty_paths:
            reasons.append(f"工作区存在清单外未提交变化：{', '.join(dirty_paths)}")
    previous_status = str(manifest.get("status", ""))
    if previous_status == "stale" and not reasons:
        reasons = list(manifest.get("stale_reasons", [])) or ["Goal 已进入 stale 终态，禁止原地恢复"]
    if completion:
        manifest["status"] = "completed"
    elif reasons:
        manifest["status"] = "stale"
    elif manifest.get("blocking_findings"):
        manifest["status"] = "blocked"
    elif previous_status == "aborted":
        manifest["status"] = "aborted"
    elif any(item.get("status") == "verification_failed" for item in manifest.get("ordered_tasks", [])):
        manifest["status"] = "verification_failed"
    elif manifest.get("checkpoints") or any(item.get("status") == "running" for item in manifest.get("ordered_tasks", [])):
        manifest["status"] = "running"
    else:
        manifest["status"] = "ready"
    manifest["status_checked_at"] = now_iso()
    manifest["stale_reasons"] = reasons
    if not getattr(args, "read_only", False):
        write_json(manifest_path, manifest)
    next_task = next((item for item in manifest.get("ordered_tasks", []) if item.get("status") != "completed"), None)
    payload = {
        "Goal ID": goal_id,
        "状态": manifest["status"],
        "目标版本": manifest.get("version", ""),
        "当前执行版本": config.get("current_version", ""),
        "过期原因": reasons,
        "完成记录当前性": "historical" if freshness_reasons else ("current" if completion else "not_applicable"),
        "当前性说明": freshness_reasons,
        "阻塞数": len(manifest.get("blocking_findings", [])),
        "下一任务": next_task.get("task_id", "") if next_task and manifest["status"] in {"ready", "running", "verification_failed"} else "",
        "最近检查点": manifest.get("checkpoints", [])[-1].get("checkpoint_id", "") if manifest.get("checkpoints") else "",
        "当前权威摘要": current_digest,
        "清单权威摘要": manifest.get("authority_digest", ""),
        "当前提交": current_commit,
        "期望提交": expected_commit,
        "初始提交": manifest.get("source_commit", ""),
        "文件": str(manifest_path.relative_to(root)),
    }
    if getattr(args, "fail_on_stale", False) and manifest["status"] == "stale":
        print_result(payload)
        return 1
    return payload


def goal_execution_reasons(root: Path, config: dict, manifest: dict, expected_commit: str) -> list[str]:
    reasons: list[str] = []
    target_config = goal_target_config(config, str(manifest.get("version", "")))
    current_digest = authority_digest(root, target_config)[0]
    current_commit = git_head(root) or ""
    if manifest.get("authority_digest") != current_digest:
        reasons.append("权威文档摘要已变化")
    if manifest.get("tool_version") != TOOL_VERSION:
        reasons.append("DAOGE Docs 工具版本已变化")
    if not goal_commit_matches_expected(root, manifest, expected_commit, current_commit):
        reasons.append("当前 HEAD 与最近受控检查点不一致")
    dirty_paths = git_dirty_paths(root, manifest.get("ignored_generated_paths", []))
    if dirty_paths:
        reasons.append(f"工作区存在清单外未提交变化：{', '.join(dirty_paths)}")
    return reasons


def command_goal_resume_context(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    goal_id = args.goal.strip().upper()
    manifest_path, manifest = load_goal_manifest(root, goal_id)
    _, expected_commit = validate_goal_checkpoint_chain(root, manifest)
    validate_goal_completion(root, manifest)
    if manifest.get("status") in {"blocked", "stale", "completed", "aborted"}:
        raise DocsError(f"Goal 当前状态不允许恢复：{manifest.get('status')}")
    reasons = goal_execution_reasons(root, config, manifest, expected_commit)
    if reasons:
        manifest["status"] = "stale"
        manifest["stale_reasons"] = reasons
        manifest["status_checked_at"] = now_iso()
        write_json(manifest_path, manifest)
        raise DocsError("Goal 恢复条件不满足：" + "；".join(reasons))
    tasks = manifest.get("ordered_tasks", [])
    next_task = next((item for item in tasks if item.get("status") != "completed"), None)
    if not next_task:
        raise DocsError("Goal 所有任务已建立检查点；请运行 goal-complete 进行最终验证")
    completed_ids = {item.get("task_id") for item in tasks if item.get("status") == "completed"}
    missing_dependencies = [item for item in next_task.get("dependencies", []) if item not in completed_ids]
    if missing_dependencies:
        raise DocsError(f"下一任务依赖尚未完成：{', '.join(missing_dependencies)}")
    next_task["status"] = "running"
    manifest["status"] = "running"
    manifest["stale_reasons"] = []
    manifest["status_checked_at"] = now_iso()
    manifest["manifest_digest"] = goal_manifest_digest(manifest)
    write_json(manifest_path, manifest)
    previous = manifest.get("checkpoints", [])[-1] if manifest.get("checkpoints") else None
    return {
        "goal_id": goal_id,
        "status": "running",
        "objective": manifest.get("objective", ""),
        "version": manifest.get("version", ""),
        "current_execution_version": config.get("current_version", ""),
        "authority_digest": manifest.get("authority_digest", ""),
        "source_commit": manifest.get("source_commit", ""),
        "resume_commit": expected_commit,
        "previous_checkpoint": previous,
        "task": next_task,
        "remaining_task_ids": [item.get("task_id") for item in tasks if item.get("status") != "completed"],
        "goal_stop_conditions": manifest.get("stop_conditions", []),
        "checkpoint_command": f"{project_python_command()} .daoge-docs/daoge_docs.py goal-checkpoint --root . --goal {goal_id} --task {next_task.get('task_id')}",
        "generated_at": now_iso(),
    }


def command_goal_checkpoint(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    goal_id = args.goal.strip().upper()
    manifest_path, manifest = load_goal_manifest(root, goal_id)
    directory = manifest_path.parent
    _, expected_parent = validate_goal_checkpoint_chain(root, manifest)
    validate_goal_completion(root, manifest)
    if manifest.get("status") not in {"running", "verification_failed"}:
        raise DocsError("Goal 必须先通过 goal-resume-context 进入 running 状态")
    static_reasons = []
    target_config = goal_target_config(config, str(manifest.get("version", "")))
    if manifest.get("authority_digest") != authority_digest(root, target_config)[0]:
        static_reasons.append("权威文档摘要已变化")
    if manifest.get("tool_version") != TOOL_VERSION:
        static_reasons.append("DAOGE Docs 工具版本已变化")
    dirty_paths = git_dirty_paths(root, manifest.get("ignored_generated_paths", []))
    if dirty_paths:
        static_reasons.append(f"工作区存在未提交变化：{', '.join(dirty_paths)}")
    if static_reasons:
        raise DocsError("不能建立检查点：" + "；".join(static_reasons))
    current_commit = git_head(root) or ""
    if not current_commit or current_commit == expected_parent:
        raise DocsError("当前任务没有形成新的 Git 提交")
    if not git_is_ancestor(root, expected_parent, current_commit):
        raise DocsError("当前 HEAD 不能追溯到最近受控检查点")
    if git_merge_commits(root, expected_parent, current_commit):
        raise DocsError("原子任务提交范围内包含 merge commit，拒绝建立检查点")
    tasks = manifest.get("ordered_tasks", [])
    task = next((item for item in tasks if item.get("status") != "completed"), None)
    if not task:
        raise DocsError("没有待建立检查点的任务；请运行 goal-complete")
    requested_task = args.task.strip().upper() if args.task else str(task.get("task_id", ""))
    if requested_task != task.get("task_id"):
        raise DocsError(f"任务顺序不允许跳跃；当前任务是 {task.get('task_id')}")
    if task.get("status") not in {"running", "verification_failed"}:
        raise DocsError("当前任务尚未通过恢复上下文进入执行态")
    all_changed_paths = git_changed_paths(root, expected_parent, current_commit)
    managed_paths = [path for path in all_changed_paths if goal_managed_git_path(manifest, path)]
    changed_paths = [path for path in all_changed_paths if path not in managed_paths]
    if not changed_paths:
        raise DocsError("当前任务提交没有授权工程路径内的文件差异")
    unauthorized = [path for path in changed_paths if not goal_path_matches(path, task.get("allowed_paths", []))]
    forbidden = [path for path in changed_paths if goal_path_matches(path, task.get("forbidden_paths", []))]
    if unauthorized:
        raise DocsError("任务提交包含授权范围外路径：" + ", ".join(unauthorized))
    if forbidden:
        raise DocsError("任务提交命中禁止路径：" + ", ".join(forbidden))
    commands = task.get("verification_commands", [])
    if not commands:
        raise DocsError("当前任务没有验证命令，不能建立检查点")
    evidence = [run_goal_verification(root, directory, manifest, command, str(task["task_id"]), current_commit) for command in commands]
    failed = [item for item in evidence if item["result"] != "passed"]
    verification_dirty_paths = git_dirty_paths(root, manifest.get("ignored_generated_paths", []))
    if verification_dirty_paths:
        failed.append(
            {
                "command_id": "WORKTREE-SIDE-EFFECT",
                "result": "failed",
                "path": "",
            }
        )
    task["last_attempt"] = {
        "commit": current_commit,
        "parent_commit": expected_parent,
        "evidence_paths": [item["path"] for item in evidence],
        "result": "failed" if failed else "passed",
        "worktree_side_effects": verification_dirty_paths,
        "created_at": now_iso(),
    }
    if failed:
        task["status"] = "verification_failed"
        manifest["status"] = "verification_failed"
        manifest["status_checked_at"] = now_iso()
        manifest["manifest_digest"] = goal_manifest_digest(manifest)
        write_json(manifest_path, manifest)
        failed_ids = ", ".join(item["command_id"] for item in failed)
        raise DocsError(f"任务验证失败，未建立检查点：{failed_ids}")
    checkpoint_id = f"CP-{len(manifest.get('checkpoints', [])) + 1:03d}"
    checkpoint_path = directory / "checkpoints" / f"{checkpoint_id}.json"
    record = {
        "schema_version": 1,
        "goal_id": goal_id,
        "checkpoint_id": checkpoint_id,
        "task_id": task["task_id"],
        "commit": current_commit,
        "parent_commit": expected_parent,
        "authority_digest": manifest["authority_digest"],
        "changed_paths": changed_paths,
        "managed_paths": managed_paths,
        "commands": [
            {
                "command_id": item["command_id"],
                "command": item["command"],
                "exit_code": item["exit_code"],
                "expected_exit_code": item["expected_exit_code"],
                "result": item["result"],
                "evidence_path": item["path"],
                "evidence_digest": item["evidence_digest"],
            }
            for item in evidence
        ],
        "exit_codes": [item["exit_code"] for item in evidence],
        "evidence_paths": [item["path"] for item in evidence],
        "created_at": now_iso(),
        "tool_version": TOOL_VERSION,
    }
    record["checkpoint_digest"] = record_digest(record, "checkpoint_digest")
    write_new(checkpoint_path, json.dumps(record, ensure_ascii=False, indent=2) + "\n")
    summary = {
        "checkpoint_id": checkpoint_id,
        "task_id": task["task_id"],
        "commit": current_commit,
        "parent_commit": expected_parent,
        "changed_paths": changed_paths,
        "managed_paths": managed_paths,
        "evidence_paths": record["evidence_paths"],
        "record_path": str(checkpoint_path.relative_to(root)),
        "checkpoint_digest": record["checkpoint_digest"],
        "created_at": record["created_at"],
    }
    manifest.setdefault("checkpoints", []).append(summary)
    task["status"] = "completed"
    task["completed_at"] = record["created_at"]
    task["checkpoint_id"] = checkpoint_id
    manifest["status"] = "running"
    manifest["status_checked_at"] = now_iso()
    manifest["manifest_digest"] = goal_manifest_digest(manifest)
    write_json(manifest_path, manifest)
    next_task = next((item for item in tasks if item.get("status") != "completed"), None)
    return {
        "Goal ID": goal_id,
        "状态": "checkpointed",
        "检查点": checkpoint_id,
        "任务": task["task_id"],
        "提交": current_commit,
        "变更路径": changed_paths,
        "证据": record["evidence_paths"],
        "下一任务": next_task.get("task_id", "") if next_task else "",
        "文件": str(checkpoint_path.relative_to(root)),
    }


def command_goal_complete(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    goal_id = args.goal.strip().upper()
    manifest_path, manifest = load_goal_manifest(root, goal_id)
    target_config = goal_target_config(config, str(manifest.get("version", "")))
    directory = manifest_path.parent
    records, expected_commit = validate_goal_checkpoint_chain(root, manifest)
    existing_completion = validate_goal_completion(root, manifest)
    if existing_completion or manifest.get("status") == "completed":
        raise DocsError("Goal 已完成，完成记录不可覆盖")
    if manifest.get("status") in {"blocked", "stale", "aborted"}:
        raise DocsError(f"Goal 当前状态不允许完成：{manifest.get('status')}")
    tasks = manifest.get("ordered_tasks", [])
    incomplete_tasks = [item.get("task_id") for item in tasks if item.get("status") != "completed"]
    if incomplete_tasks:
        raise DocsError("仍有任务未建立通过检查点：" + ", ".join(incomplete_tasks))
    if len(records) != len(tasks):
        raise DocsError("任务数与受控检查点数不一致")
    reasons = goal_execution_reasons(root, config, manifest, expected_commit)
    if reasons:
        manifest["status"] = "stale"
        manifest["stale_reasons"] = reasons
        manifest["status_checked_at"] = now_iso()
        write_json(manifest_path, manifest)
        raise DocsError("Goal 完成条件不满足：" + "；".join(reasons))
    generate_indexes(root, config)
    target_is_current = str(target_config["current_version"]) == str(config["current_version"])
    check_errors, _ = collect_checks(root, target_config, check_derived=target_is_current)
    gate_errors: list[str] = []
    version_errors, _ = collect_gate(root, target_config, "version-ready", None, check_derived=target_is_current)
    gate_errors.extend(version_errors)
    for feature_id in manifest.get("feature_ids", []):
        feature_errors, _ = collect_gate(root, target_config, "feature-ready", str(feature_id), check_derived=target_is_current)
        gate_errors.extend(feature_errors)
    structural_errors = sorted(set(check_errors + gate_errors))
    browser_errors, _ = browser_smoke(root, config)
    structural_errors = sorted(set(structural_errors + browser_errors))
    if structural_errors:
        manifest["status"] = "verification_failed"
        manifest["last_completion_attempt"] = {
            "commit": expected_commit,
            "result": "failed",
            "structural_errors": structural_errors,
            "created_at": now_iso(),
        }
        manifest["manifest_digest"] = goal_manifest_digest(manifest)
        write_json(manifest_path, manifest)
        summary = "；".join(normalize_goal_issue(root, item) for item in structural_errors[:3])
        raise DocsError(f"Goal 最终文档检查或 Ready 门禁失败：{len(structural_errors)} 项：{summary}")
    final_evidence = [
        run_goal_verification(root, directory, manifest, command, "FINAL", expected_commit)
        for command in manifest.get("verification_commands", [])
    ]
    failed = [item for item in final_evidence if item["result"] != "passed"]
    verification_dirty_paths = git_dirty_paths(root, manifest.get("ignored_generated_paths", []))
    if verification_dirty_paths:
        failed.append(
            {
                "command_id": "WORKTREE-SIDE-EFFECT",
                "result": "failed",
                "path": "",
            }
        )
    manifest["last_completion_attempt"] = {
        "commit": expected_commit,
        "result": "failed" if failed else "passed",
        "evidence_paths": [item["path"] for item in final_evidence],
        "worktree_side_effects": verification_dirty_paths,
        "created_at": now_iso(),
    }
    if failed:
        manifest["status"] = "verification_failed"
        manifest["manifest_digest"] = goal_manifest_digest(manifest)
        write_json(manifest_path, manifest)
        failed_ids = ", ".join(item["command_id"] for item in failed)
        raise DocsError(f"Goal 最终验证失败，不能标记 completed：{failed_ids}")
    completion_path = directory / "completion.json"
    completion = {
        "schema_version": 1,
        "goal_id": goal_id,
        "status": "completed",
        "objective": manifest.get("objective", ""),
        "version": manifest.get("version", ""),
        "source_commit": manifest.get("source_commit", ""),
        "final_commit": expected_commit,
        "authority_digest": manifest.get("authority_digest", ""),
        "task_ids": [item.get("task_id") for item in tasks],
        "checkpoint_ids": [item.get("checkpoint_id") for item in records],
        "verification_evidence_paths": [item["path"] for item in final_evidence],
        "docs_check": "passed",
        "version_ready": "passed",
        "feature_ready": {str(item): "passed" for item in manifest.get("feature_ids", [])},
        "completed_at": now_iso(),
        "tool_version": TOOL_VERSION,
        "release_allowed": False,
        "release_note": "开发级 Goal 完成不代表允许发布；发布仍须通过 release 门禁。",
    }
    completion["completion_digest"] = record_digest(completion, "completion_digest")
    write_new(completion_path, json.dumps(completion, ensure_ascii=False, indent=2) + "\n")
    manifest["completion"] = {
        "record_path": str(completion_path.relative_to(root)),
        "completion_digest": completion["completion_digest"],
        "commit": expected_commit,
        "completed_at": completion["completed_at"],
    }
    manifest["completed_at"] = completion["completed_at"]
    manifest["status"] = "completed"
    manifest["status_checked_at"] = now_iso()
    manifest["manifest_digest"] = goal_manifest_digest(manifest)
    write_json(manifest_path, manifest)
    return {
        "Goal ID": goal_id,
        "状态": "completed",
        "最终提交": expected_commit,
        "检查点数": len(records),
        "最终验证数": len(final_evidence),
        "完成记录": str(completion_path.relative_to(root)),
        "发布说明": completion["release_note"],
    }


def command_check(args: argparse.Namespace) -> int:
    root = project_root(args.root)
    config = load_config(root)
    errors, warnings = collect_checks(root, config)
    return emit_report(errors, warnings, args.json, "docs-check")


def command_audit(args: argparse.Namespace) -> int:
    root = project_root(args.root)
    config = load_config(root)
    errors, warnings = collect_checks(root, config)
    browser_errors, browser_resources = browser_smoke(root, config)
    errors.extend(browser_errors)
    docs = docs_root(root, config)
    records = feature_documents(root, config)
    all_records = all_feature_documents(root, config)
    domain_dirs = {record["path"].parent for record in all_records}
    portfolio = browser_version_portfolio(root, config, browser_records(root, config))
    future_cards = [
        item for item in portfolio.get("versions", [])
        if str(item.get("id", "")) != str(config["current_version"])
        and str(item.get("role", "")).lower() in {"future", "planning"}
    ]
    selector_path = root / ".daoge-docs" / "evidence.json"
    selected_count = 0
    if selector_path.exists():
        selector = read_json(selector_path, "当前证据清单")
        selected = selector.get("selected", {})
        if isinstance(selected, dict):
            selected_count = sum(1 for value in selected.values() if value)
    metrics = {
        "文档文件数": len([path for path in docs.rglob("*") if path.is_file()]),
        "Markdown 数": len(list(docs.rglob("*.md"))),
        "领域数": len(domain_dirs),
        "功能数": len(all_records),
        "当前版本功能数": len(records),
        "高风险功能数": sum(1 for record in all_records if record["meta"].get("risk") == "high"),
        "当前版本高风险功能数": sum(1 for record in records if record["meta"].get("risk") == "high"),
        "E2E 用例数": len(e2e_documents(root, config)),
        "ADR 数": len(adr_documents(root, config)),
        "冻结决策数": len(decision_records(root, config)),
        "后续版本规划数": len(future_cards),
        "后续版本规划文件数": sum(1 for item in future_cards if item.get("overview_path")),
        "当前证据报告数": selected_count,
        "工作台 Smoke 资源数": len(browser_resources),
        "待决文档数": len({warning.split("：", 1)[-1] for warning in warnings if warning.startswith("仍有待决占位")}),
    }
    browser_html = docs / "90-参考资料/产品文档浏览器.html"
    browser_data = docs / "90-参考资料/产品文档浏览器-文档数据.js"
    browser_html_text = browser_html.read_text(encoding="utf-8") if browser_html.exists() else ""
    browser_data_text = browser_data.read_text(encoding="utf-8") if browser_data.exists() else ""
    browser_complete = all(
        marker in browser_html_text
        for marker in [
            'data-view="workbench"',
            'data-view="overview"',
            'data-view="reader"',
            'data-view="map"',
            'data-view="evolution"',
            'data-view="timeline"',
            "function renderMarkdown",
            "function collectMarkdownReferences",
            "function parseMarkdownList",
            "function markdownTableCells",
            "function markdownLink",
            "function renderSearch",
            "function renderVerificationPanel",
            "function renderChangeSummary",
            "function renderProductArchitectureMap",
            "function renderCoreFlowMap",
            "function renderVersionRoadmapMap",
            "function renderDataDomainsMap",
            "function renderDeliveryTraceMap",
            "function renderRiskHotspotsMap",
            "function renderFlowRail",
            "function readerHref",
            "function documentMatchLocation",
            "function restoreReaderPosition",
            "function readerPositionKey",
            "function readerContext",
            "function goalPreparationPrompt",
            'data-copy-goal-prompt',
            "复制 Goal 提示",
            "打开 Markdown 原文",
            'aria-label="关闭文档目录"',
            'aria-label="关闭阅读辅助"',
            "input.setSelectionRange",
            ".article th, .article td { min-width: 104px; }",
            "catch { if (location.hash !== hash) location.hash = hash; }",
        ]
    ) and all(marker in browser_data_text for marker in ['"schema_version":8', '"documents":', '"directories":', '"entities":', '"content":', '"content_digest":', '"sections":', '"features":', '"requirements":', '"relations":', '"findings":', '"task_packets":', '"governance":', '"views":', '"version_portfolio":', '"active_execution_version":', '"navigation":', '"change_summary":', '"goal_readiness":', '"design_depth":', '"evidence_binding":'])
    script_text = SCRIPT_PATH.read_text(encoding="utf-8")
    utf8_delivery_complete = all(
        marker in script_text
        for marker in [
            "class Utf8DocsRequestHandler",
            "def command_serve",
            'add_parser("serve"',
            "charset=utf-8",
        ]
    )
    goal_commands_complete = all(
        marker in script_text
        for marker in [
            "def command_prepare_goal",
            "def command_goal_status",
            "def command_goal_resume_context",
            "def command_goal_checkpoint",
            "def command_goal_complete",
            'add_parser("prepare-goal"',
            'add_parser("goal-status"',
            'add_parser("goal-resume-context"',
            'add_parser("goal-checkpoint"',
            'add_parser("goal-complete"',
            "manifest_digest",
            "authority_digest",
            "source_commit",
        ]
    )
    integration_templates_complete = all(
        (root / ".daoge-docs" / "assets" / "templates" / "integrations" / name).exists()
        for name in ["github-actions.yml", "pull-request-template.md", "vscode-tasks.json", "AGENTS-snippet.md"]
    )
    capabilities = {
        "核心目录与职责": not any("Profile 必需文件" in error for error in errors),
        "文档章节与治理元数据": not any("治理文档" in error for error in errors),
        "稳定需求与追踪矩阵": (docs / "03-功能规格" / str(config["current_version"]) / f"00-{config['current_version']}需求追踪矩阵.md").exists(),
        "领域与功能生成": bool(records) and all((directory / "README.md").exists() for directory in domain_dirs),
        "高风险技术设计": all(record["meta"].get("risk") != "high" or record["path"].with_name(record["path"].stem + "-技术设计.md").exists() for record in records),
        "可解释设计与分支追踪": all(not validate_feature_design_depth(record) for record in records),
        "专项门禁与测试契约": not validate_specialized_document_contracts(root, config),
        "E2E 执行空间": len(e2e_documents(root, config)) > 0,
        "性能与容量空间": (docs / "05-测试与发布/性能与容量/负载模型.md").exists(),
        "发布、回滚与恢复": all((docs / path).exists() for path in [Path("05-测试与发布/发布/部署手册.md"), Path("05-测试与发布/发布/回滚手册.md"), Path("05-测试与发布/发布/恢复手册.md")]),
        "决策治理": bool(adr_documents(root, config) or decision_records(root, config)),
        # A V1-only product must preserve a future-version planning space without
        # inventing V2 business commitments solely to satisfy an audit checkbox.
        "版本演进规划": (docs / "02-产品与版本" / "后续版本" / "README.md").exists(),
        "可视化与完整文档浏览器": browser_complete and (docs / "02-产品与版本/图表/功能演进-版本主链路.svg").exists(),
        "UTF-8 来源阅读与本地服务": utf8_delivery_complete,
        "Goal 可恢复执行生命周期": goal_commands_complete,
        "CI、PR、IDE 与智能体集成模板": integration_templates_complete,
        "四类当前证据": selected_count == len(EVIDENCE_TYPES),
    }
    payload = {
        "审计": "daoge-docs-reference-depth",
        "Profile": config["profile"],
        "结构检查通过": not errors,
        "达到参考 docs 的能力深度": all(capabilities.values()) and not errors,
        "能力": capabilities,
        "指标": metrics,
        "错误": errors,
        "警告": warnings,
        "边界": "能力深度通过不代表业务内容、实现或发布证据与参考项目相同。",
    }
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print(f"参考深度审计：{'通过' if payload['达到参考 docs 的能力深度'] else '未通过'}")
        for name, passed in capabilities.items():
            print(f"{'通过' if passed else '缺失'}：{name}")
        print(json.dumps(metrics, ensure_ascii=False, indent=2))
    return 0 if payload["达到参考 docs 的能力深度"] else 1


def command_gate(args: argparse.Namespace) -> int:
    root = project_root(args.root)
    config = load_config(root)
    errors, warnings = collect_gate(root, config, args.stage, args.feature)
    return emit_report(errors, warnings, args.json, f"docs-gate:{args.stage}")


def print_result(result: dict) -> None:
    print(json.dumps(result, ensure_ascii=False, indent=2))


def build_parser() -> argparse.ArgumentParser:
    parser = ChineseArgumentParser(description="DAOGE Docs 中文文档驱动开发治理工具")
    subparsers = parser.add_subparsers(dest="command", required=True, parser_class=ChineseArgumentParser)

    init = subparsers.add_parser("init", help="初始化中文项目文档体系")
    init.add_argument("--root", default=".", help="项目根目录")
    init.add_argument("--project-name", required=True, help="项目中文名称")
    init.add_argument("--project-code", required=True, help="稳定项目代码，例如 TAG")
    init.add_argument("--version", default="V1", help="当前版本")
    init.add_argument("--profile", choices=sorted(PROFILES), default="strict", help="文档治理深度，默认 strict")
    init.add_argument("--merge", action="store_true", help="只向已有 docs 补充缺失文件，不覆盖项目事实")
    init.add_argument("--github-actions", action="store_true", help="安装 GitHub Actions 文档检查")
    init.set_defaults(handler=command_init)

    upgrade = subparsers.add_parser("upgrade", help="升级项目内工具和 Profile，保留项目文档事实")
    upgrade.add_argument("--root", default=".")
    upgrade.add_argument("--profile", choices=sorted(PROFILES))
    upgrade.set_defaults(handler=command_upgrade)

    integrations = subparsers.add_parser("install-integrations", help="安装不覆盖现有配置的 CI、PR、IDE 与智能体入口")
    integrations.add_argument("--root", default=".")
    integrations.add_argument("--target", action="append", choices=["github", "vscode", "agents"], help="可重复选择；默认安装全部")
    integrations.set_defaults(handler=command_install_integrations)

    version = subparsers.add_parser("new-version", help="创建新版本文档空间")
    version.add_argument("--root", default=".")
    version.add_argument("--version", required=True)
    version.add_argument("--no-activate", dest="activate", action="store_false", help="仅创建规划空间，不切换当前版本")
    version.set_defaults(handler=command_new_version, activate=True)

    future_version = subparsers.add_parser("new-future-version", help="创建后续版本规划骨架，不激活版本")
    future_version.add_argument("--root", default=".")
    future_version.add_argument("--version", required=True)
    future_version.add_argument("--name", required=True)
    future_version.set_defaults(handler=command_new_future_version)

    domain = subparsers.add_parser("new-domain", help="创建领域说明和功能目录")
    domain.add_argument("--root", default=".")
    domain.add_argument("--name", required=True)
    domain.set_defaults(handler=command_new_domain)

    architecture = subparsers.add_parser("new-architecture-spec", help="创建生命周期、协议、接入或其他架构专项")
    architecture.add_argument("--root", default=".")
    architecture.add_argument("--name", required=True)
    architecture.add_argument("--key", required=True, help="稳定规格代码，例如 DRIVER")
    architecture.add_argument("--kind", choices=["lifecycle", "protocol", "integration", "extension"], required=True)
    architecture.add_argument("--with-example", action="store_true", help="同时创建 YAML 示例和 JSON fixture")
    architecture.set_defaults(handler=command_new_architecture_spec)

    feature = subparsers.add_parser("new-feature", help="创建中文功能规格和必要的高风险技术设计")
    feature.add_argument("--root", default=".")
    feature.add_argument("--number", required=True, type=int)
    feature.add_argument("--name", required=True)
    feature.add_argument("--domain", required=True)
    feature.add_argument("--risk", choices=sorted(RISKS), default="standard")
    feature.add_argument("--risk-reason", default="标准业务变更")
    feature.add_argument("--evolution-track", default="", help="显式关联 TRACK-* 能力主线")
    feature.add_argument("--keywords", default="")
    feature.add_argument("--requirements", default="", help="逗号分隔的关联 NFR/RG ID")
    feature.add_argument("--forbidden-paths", default="", help="逗号分隔的禁止修改工程路径；包含子路径")
    feature.set_defaults(handler=command_new_feature)

    requirement = subparsers.add_parser("new-requirement", help="注册稳定 NFR 或 RG")
    requirement.add_argument("--root", default=".")
    requirement.add_argument("--type", choices=["NFR", "RG", "nfr", "rg"], required=True)
    requirement.add_argument("--number", type=int)
    requirement.add_argument("--name", required=True)
    requirement.add_argument("--source", required=True, help="项目 docs 内真实存在的需求权威来源文件")
    requirement.add_argument("--verification", required=True, help="验证方式或证据入口")
    requirement.set_defaults(handler=command_new_requirement)

    e2e = subparsers.add_parser("new-e2e", help="创建中文 E2E 验收用例")
    e2e.add_argument("--root", default=".")
    e2e.add_argument("--number", required=True, type=int)
    e2e.add_argument("--name", required=True)
    e2e.add_argument("--requirements", required=True, help="逗号分隔的需求 ID")
    e2e.add_argument("--environment-level", choices=["local-mock", "integration", "staging", "production-gate"], default="staging")
    e2e.set_defaults(handler=command_new_e2e)

    adr = subparsers.add_parser("new-adr", help="创建下一个 ADR")
    adr.add_argument("--root", default=".")
    adr.add_argument("--title", required=True)
    adr.add_argument("--requirements", default="")
    adr.set_defaults(handler=command_new_adr)

    decision = subparsers.add_parser("new-decision", help="登记稳定冻结决策；工具不会自行批准")
    decision.add_argument("--root", default=".")
    decision.add_argument("--title", required=True)
    decision.add_argument("--decision", required=True)
    decision.add_argument("--rationale", required=True)
    decision.add_argument("--requirements", default="")
    decision.add_argument("--affected", required=True)
    decision.add_argument("--status", choices=["proposed", "accepted", "deprecated"], default="proposed")
    decision.add_argument("--confirmed-by", default="")
    decision.add_argument("--supersedes", default="")
    decision.set_defaults(handler=command_new_decision)

    task = subparsers.add_parser("new-task", help="从已冻结功能创建开发任务书")
    task.add_argument("--root", default=".")
    task.add_argument("--feature", required=True)
    task.add_argument("--name", required=True)
    task.set_defaults(handler=command_new_task)

    evidence = subparsers.add_parser("new-evidence", help="创建并选择机器可读证据报告")
    evidence.add_argument("--root", default=".")
    evidence.add_argument("--type", choices=sorted(EVIDENCE_TYPES), required=True)
    evidence.add_argument("--environment", required=True)
    evidence.add_argument("--commit", required=True)
    evidence.add_argument("--build-id", required=True)
    evidence.add_argument("--no-select", dest="select", action="store_false", help="不设为当前证据")
    evidence.set_defaults(handler=command_new_evidence, select=True)

    reference = subparsers.add_parser("new-reference", help="创建非权威调研或外部资料记录")
    reference.add_argument("--root", default=".")
    reference.add_argument("--name", required=True)
    reference.add_argument("--source-date", required=True)
    reference.add_argument("--review-after", required=True)
    reference.set_defaults(handler=command_new_reference)

    archive = subparsers.add_parser("archive", help="创建历史归档并记录当前替代权威")
    archive.add_argument("--root", default=".")
    archive.add_argument("--name", required=True)
    archive.add_argument("--source", required=True)
    archive.add_argument("--replacement", required=True)
    archive.add_argument("--reason", required=True)
    archive.set_defaults(handler=command_archive)

    index = subparsers.add_parser("index", help="重新生成全部索引、矩阵和状态视图")
    index.add_argument("--root", default=".")
    index.set_defaults(handler=command_index)

    doctor = subparsers.add_parser("doctor", help="只读检查运行环境、Git 状态和技术栈候选")
    doctor.add_argument("--root", default=".")
    doctor.add_argument("--json", action="store_true")
    doctor.set_defaults(handler=command_doctor)

    ci_check = subparsers.add_parser("ci-check", help="重建派生文档并检查 docs、工作台与 Goal 基线")
    ci_check.add_argument("--root", default=".")
    ci_check.add_argument("--json", action="store_true")
    ci_check.set_defaults(handler=command_ci_check)

    serve = subparsers.add_parser("serve", help="启动仅绑定本机且显式使用 UTF-8 的只读文档服务")
    serve.add_argument("--root", default=".")
    serve.add_argument("--host", choices=["127.0.0.1", "localhost"], default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8877)
    serve.set_defaults(handler=command_serve)

    browser_check = subparsers.add_parser("browser-check", help="执行工作台来源、视图和 UTF-8 服务 Smoke 验收")
    browser_check.add_argument("--root", default=".")
    browser_check.add_argument("--json", action="store_true")
    browser_check.set_defaults(handler=command_browser_check)

    snapshot = subparsers.add_parser("snapshot", help="创建不可变版本快照，供变更检测、Goal 恢复和审计使用")
    snapshot.add_argument("--root", default=".")
    snapshot.add_argument("--version", help="快照版本，默认使用当前活动版本")
    snapshot.add_argument("--commit", help="显式绑定的 Git commit，默认读取当前 HEAD")
    snapshot.set_defaults(handler=command_snapshot)

    digest = subparsers.add_parser("authority-digest", help="计算当前权威文档集合的稳定 SHA-256 摘要")
    digest.add_argument("--root", default=".")
    digest.set_defaults(handler=command_authority_digest)

    prepare_goal = subparsers.add_parser("prepare-goal", help="从已冻结功能生成确定性 Goal 执行清单")
    prepare_goal.add_argument("--root", default=".")
    prepare_goal.add_argument("--version", help="目标版本；默认使用当前执行版本，显式指定时不改变项目活动版本")
    prepare_goal.add_argument("--feature", action="append", required=True, help="目标版本功能 ID，可重复或使用逗号分隔")
    prepare_goal.add_argument("--goal-id", help="显式 Goal ID；默认按目标版本分配下一个编号")
    prepare_goal.add_argument("--objective", help="单句、可验证的 Goal 目标")
    prepare_goal.set_defaults(handler=command_prepare_goal)

    goal_status = subparsers.add_parser("goal-status", help="重新评估 Goal 的基线、权威摘要和过期状态")
    goal_status.add_argument("--root", default=".")
    goal_status.add_argument("--goal", required=True, help="要检查的 GOAL-* ID")
    goal_status.add_argument("--read-only", action="store_true", help="只评估，不回写状态与检查时间")
    goal_status.add_argument("--fail-on-stale", action="store_true", help="检测到 stale 时返回非零退出码，供 CI 使用")
    goal_status.set_defaults(handler=command_goal_status)

    goal_resume = subparsers.add_parser("goal-resume-context", help="验证恢复条件并输出唯一下一任务上下文")
    goal_resume.add_argument("--root", default=".")
    goal_resume.add_argument("--goal", required=True, help="要开始或恢复的 GOAL-* ID")
    goal_resume.set_defaults(handler=command_goal_resume_context)

    goal_checkpoint = subparsers.add_parser("goal-checkpoint", help="执行任务验证并建立受控 Git 检查点")
    goal_checkpoint.add_argument("--root", default=".")
    goal_checkpoint.add_argument("--goal", required=True, help="正在执行的 GOAL-* ID")
    goal_checkpoint.add_argument("--task", help="当前 TASK-* ID；省略时使用唯一下一任务")
    goal_checkpoint.set_defaults(handler=command_goal_checkpoint)

    goal_complete = subparsers.add_parser("goal-complete", help="复验全部任务、命令和门禁并结束 Goal")
    goal_complete.add_argument("--root", default=".")
    goal_complete.add_argument("--goal", required=True, help="要完成的 GOAL-* ID")
    goal_complete.set_defaults(handler=command_goal_complete)

    check = subparsers.add_parser("check", help="检查结构、链接、ID、中文规范和追踪关系")
    check.add_argument("--root", default=".")
    check.add_argument("--json", action="store_true")
    check.set_defaults(handler=command_check)

    audit = subparsers.add_parser("audit", help="审计是否达到参考 docs 的完整能力深度")
    audit.add_argument("--root", default=".")
    audit.add_argument("--json", action="store_true")
    audit.set_defaults(handler=command_audit)

    gate = subparsers.add_parser("gate", help="执行发现、版本、功能或发布门禁")
    gate.add_argument("--root", default=".")
    gate.add_argument("--stage", choices=["discovery", "version-ready", "feature-ready", "ready", "release"], required=True)
    gate.add_argument("--feature")
    gate.add_argument("--json", action="store_true")
    gate.set_defaults(handler=command_gate)
    return parser


def main() -> int:
    configure_utf8_stdio()
    parser = build_parser()
    args = parser.parse_args()
    try:
        result = args.handler(args)
        if isinstance(result, int):
            return result
        print_result(result)
        return 0
    except DocsError as exc:
        print(f"错误：{exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
